"use client";

import { FormEvent, useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import { authClient } from "@/lib/auth-client";
import type { Activity, ActivityTemplate, ActivityType, Cadence, CadenceStep, Lead, LeadEvent, LeadStatus, LossReason, Organization, OrganizationSettings, Profile, UserInvite, FeedbackRequest, LeadImport, WebhookIntegration } from "@/lib/types";

const DARK_LOGO="https://res.cloudinary.com/dofv1fbu6/image/upload/v1789318165/VEROSS-PROSPECFLOW-DARKMODE_vflx76.png";
const LIGHT_LOGO="https://res.cloudinary.com/dofv1fbu6/image/upload/v1789318165/VEROSS-PROSPECFLOW-LIGHTMODE_ran1t8.png";
const activityLabels:Record<ActivityType,string>={call:"Ligação",email:"E-mail",whatsapp:"WhatsApp",linkedin:"LinkedIn",instagram:"Instagram",in_person:"Visita presencial",meeting:"Reunião",research:"Pesquisa",custom:"Tarefa personalizada"};
const activityIcons:Record<ActivityType,string>={call:"☎",email:"✉",whatsapp:"WA",linkedin:"in",instagram:"◎",in_person:"⌖",meeting:"◉",research:"⌕",custom:"＋"};
const selectableActivityTypes=(Object.entries(activityLabels) as [ActivityType,string][]).filter(([type])=>type!=="meeting");
const statusLabels:Record<LeadStatus,string>={new:"Novo",prospecting:"Em prospecção",connected:"Conectado",qualified:"Qualificado",won:"Ganho",paused:"Pausado",lost:"Perdido",archived:"Arquivado"};
const defaultPermissions={admin:{view_all_leads:true,delete_leads:true,import_leads:true,create_leads:true,reassign_leads:true,access_war_room:true,manage_cadences:true,manage_users:true},manager:{view_all_leads:true,delete_leads:true,import_leads:true,create_leads:true,reassign_leads:true,access_war_room:true,manage_cadences:true,manage_users:false},member:{view_all_leads:false,delete_leads:false,import_leads:false,create_leads:true,reassign_leads:false,access_war_room:false,manage_cadences:false,manage_users:false}};
const defaultSettings:OrganizationSettings={weekly_goal:100,daily_activity_goal:20,conversion_goal_pct:10,meeting_goal:5,monthly_gain_goal:10,work_days:[1,2,3,4,5],work_start:"08:00",work_end:"18:00",custom_fields:[],score_rules:"",score_rules_v2:[],feedback_prompt:"A reunião resultou em ganho?",blocklist:[],default_role:"member",email_sender_name:"",email_reply_to:"",role_permissions:defaultPermissions};
type Section="central"|"battle"|"leads"|"setup"|"warroom"|"lead";
type ModalName="lead"|"activity"|"editLead"|"ignore"|"lost"|"import"|"importHistory"|"cadence"|"activityTemplate"|"account"|"reopen"|null;

export default function ProspecFlowApp({backendConfigured}:{backendConfigured:boolean}){
  const router=useRouter();
  const [theme,setTheme]=useState<"dark"|"light">("dark");
  const [section,setSection]=useState<Section>("central");
  const [leads,setLeads]=useState<Lead[]>([]); const [activities,setActivities]=useState<Activity[]>([]); const [cadences,setCadences]=useState<Cadence[]>([]); const [activityTemplates,setActivityTemplates]=useState<ActivityTemplate[]>([]);
  const [lossReasons,setLossReasons]=useState<LossReason[]>([]); const [events,setEvents]=useState<LeadEvent[]>([]); const [profiles,setProfiles]=useState<Profile[]>([]); const [invites,setInvites]=useState<UserInvite[]>([]); const [feedbackRequests,setFeedbackRequests]=useState<FeedbackRequest[]>([]); const [leadImports,setLeadImports]=useState<LeadImport[]>([]); const [integrations,setIntegrations]=useState<WebhookIntegration[]>([]); const [currentProfile,setCurrentProfile]=useState<Profile|null>(null);
  const [settings,setSettings]=useState<OrganizationSettings>(defaultSettings); const [organization,setOrganization]=useState<Organization|null>(null);
  const [selectedLeadId,setSelectedLeadId]=useState(""); const [selectedActivityId,setSelectedActivityId]=useState(""); const [outcomeActivityId,setOutcomeActivityId]=useState(""); const [editingCadence,setEditingCadence]=useState<Cadence|null>(null); const [editingTemplate,setEditingTemplate]=useState<ActivityTemplate|null>(null);
  const [search,setSearch]=useState(""); const [statusFilter,setStatusFilter]=useState("active"); const [cadenceFilter,setCadenceFilter]=useState("");
  const [modal,setModal]=useState<ModalName>(null); const [loading,setLoading]=useState(backendConfigured); const [notice,setNotice]=useState("");
  const [userMenu,setUserMenu]=useState(false); const [accountTab,setAccountTab]=useState("profile");
  const [completionPrompt,setCompletionPrompt]=useState<{leadId:string;leadName:string}|null>(null);

  useEffect(()=>{const saved=localStorage.getItem("prospecflow-theme") as "dark"|"light"|null;if(saved)setTheme(saved);if(backendConfigured)void loadData();else setLoading(false)},[backendConfigured]);
  useEffect(()=>{if(!notice)return;const timer=window.setTimeout(()=>setNotice(""),3000);return()=>window.clearTimeout(timer)},[notice]);
  useEffect(()=>{if(!completionPrompt)return;const timer=window.setTimeout(()=>setCompletionPrompt(null),5000);return()=>window.clearTimeout(timer)},[completionPrompt]);
  useEffect(()=>{const confirmClick=(event:MouseEvent)=>{const button=(event.target as HTMLElement).closest("button");if(!button||button.disabled||button.dataset.feedback==="off")return;button.classList.remove("click-confirmed");void button.offsetWidth;button.classList.add("click-confirmed");window.setTimeout(()=>button.classList.remove("click-confirmed"),1100)};document.addEventListener("click",confirmClick,true);return()=>document.removeEventListener("click",confirmClick,true)},[]);
  async function loadData(){const response=await fetch("/api/workspace",{cache:"no-store"});if(response.status===401){router.replace("/auth");return}if(response.status===403){setNotice("Seu acesso está suspenso. Fale com o administrador da conta.");setLoading(false);return}if(!response.ok){setNotice("Não foi possível carregar os dados.");setLoading(false);return}const d=await response.json();setLeads(d.leads||[]);setActivities(d.activities||[]);setCadences(d.cadences||[]);setActivityTemplates(d.activityTemplates||[]);setLossReasons(d.lossReasons||[]);setSettings({...defaultSettings,...(d.settings||{}),role_permissions:d.settings?.role_permissions||defaultPermissions});setProfiles(d.profiles||[]);setInvites(d.invites||[]);setFeedbackRequests(d.feedbackRequests||[]);setLeadImports(d.leadImports||[]);setIntegrations(d.integrations||[]);setCurrentProfile(d.currentProfile||null);setEvents(d.events||[]);setOrganization(d.organization||null);if(!selectedLeadId&&d.leads?.[0])setSelectedLeadId(d.leads[0].id);setLoading(false)}
  async function post(action:string,payload:Record<string,unknown>={},success?:string){const response=await fetch("/api/workspace",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({action,...payload})});const result=await response.json();if(!response.ok){setNotice(result.error||"Não foi possível concluir.");return null}await loadData();if(success)setNotice(success);return result}
  const selectedLead=leads.find(l=>l.id===selectedLeadId); const selectedActivity=activities.find(a=>a.id===selectedActivityId);
  const pending=useMemo(()=>activities.filter(a=>a.status==="pending").sort((a,b)=>+new Date(a.due_at)-+new Date(b.due_at)),[activities]);
  const battlePending=useMemo(()=>pending.filter(a=>isToday(a.due_at)),[pending]);
  const overdue=pending.filter(a=>new Date(a.due_at)<new Date());
  const filteredLeads=leads.filter(l=>{const text=`${l.first_name} ${l.last_name} ${l.company} ${l.email}`.toLowerCase();const statusOk=statusFilter==="all"||(statusFilter==="active"?l.status!=="archived":l.status===statusFilter);return text.includes(search.toLowerCase())&&statusOk&&(!cadenceFilter||l.cadence_id===cadenceFilter)});
  const can=(key:keyof typeof defaultPermissions.member)=>{if(!currentProfile)return false;if(currentProfile.role==="owner")return true;return Boolean(settings.role_permissions[currentProfile.role]?.[key])};
  const trialDays=organization?.plan_status==="active"?null:Math.max(0,Math.ceil((new Date(organization?.trial_ends_at||Date.now()).getTime()-Date.now())/86400000));
  const trialDay=organization?.plan_status==="active"?null:Math.min(23,Math.max(1,Math.floor((Date.now()-new Date(organization?.created_at||Date.now()).getTime())/86400000)+1));
  const trialExpired=organization?.plan_status!=="active"&&organization&&new Date(organization.trial_ends_at)<new Date();
  function toggleTheme(){const next=theme==="dark"?"light":"dark";setTheme(next);localStorage.setItem("prospecflow-theme",next)}
  function openLead(id:string){setSelectedLeadId(id);setSection("lead")}
  async function signOut(){if(backendConfigured)await authClient.signOut();router.push("/auth")}

  async function createLead(event:FormEvent<HTMLFormElement>){event.preventDefault();const f=new FormData(event.currentTarget);const lead=formLead(f,settings.custom_fields);const result=await post("createLead",{lead,cadenceId:String(f.get("cadence_id"))},"Lead incluído na cadência.");if(result){setModal(null);setSelectedLeadId(result.data.id);setSection("lead")}}
  async function updateLead(event:FormEvent<HTMLFormElement>){event.preventDefault();if(!selectedLead)return;const lead={...formLead(new FormData(event.currentTarget),settings.custom_fields),id:selectedLead.id,observations:selectedLead.observations||""};if(await post("updateLead",{lead},"Dados atualizados."))setModal(null)}
  async function createActivity(event:FormEvent<HTMLFormElement>){event.preventDefault();if(!selectedLead)return;const f=new FormData(event.currentTarget);const activity={lead_id:selectedLead.id,type:String(f.get("type")),title:String(f.get("title")),due_at:new Date(String(f.get("due_at"))).toISOString(),notes:String(f.get("notes")||"")};if(await post("createActivity",{activity},"Atividade adicionada."))setModal(null)}
  async function finishActivity(action:"completeActivity"|"skipActivity",id:string,notes=""){const activity=activities.find(a=>a.id===id),lead=activity&&leads.find(l=>l.id===activity.lead_id);const result=await post(action,{id,notes},action==="completeActivity"?"Atividade concluída.":"Atividade ignorada.");if(result&&action==="completeActivity"&&lead)setCompletionPrompt({leadId:lead.id,leadName:`${lead.first_name} ${lead.last_name}`.trim()})}
  async function ignoreActivity(event:FormEvent<HTMLFormElement>){event.preventDefault();if(!selectedActivity)return;const notes=String(new FormData(event.currentTarget).get("notes")||"").trim();if(!notes){setNotice("Informe a justificativa para ignorar a atividade.");return}if(await post("skipActivity",{id:selectedActivity.id,notes},"Atividade ignorada."))setModal(null)}
  async function loseLead(event:FormEvent<HTMLFormElement>){event.preventDefault();if(!selectedLead)return;const f=new FormData(event.currentTarget);if(await post("setLeadStatus",{id:selectedLead.id,status:"lost",lossReasonId:String(f.get("loss_reason_id")),activityId:outcomeActivityId||undefined},"Lead marcado como perdido.")){setOutcomeActivityId("");setModal(null)}}
  async function reopenLead(event:FormEvent<HTMLFormElement>){event.preventDefault();if(!selectedLead)return;const f=new FormData(event.currentTarget);const payload={id:selectedLead.id,cadenceId:String(f.get("cadence_id")||""),assignedTo:can("reassign_leads")?String(f.get("assigned_to")||""):undefined};if(await post("reopenLead",payload,"Lead reaberto com uma nova jornada."))setModal(null)}
  function openChannel(a:Activity,lead?:Lead){if(!lead)return;const phone=(lead.phone||"").replace(/\D/g,"");const urls:Partial<Record<ActivityType,string>>={call:`tel:${phone}`,email:`mailto:${lead.email}`,whatsapp:`https://wa.me/55${phone}`,linkedin:`https://www.linkedin.com/search/results/all/?keywords=${encodeURIComponent(`${lead.first_name} ${lead.last_name} ${lead.company}`)}`,instagram:`https://www.instagram.com/`};const url=urls[a.type];if(url)window.open(url,"_blank","noopener,noreferrer");else setNotice("Esta atividade é executada fora do navegador.")}

  if(loading)return <div className="loading">Preparando sua Central…</div>;
  if(trialExpired)return <div className="paywall"><img src={DARK_LOGO} alt="Veross ProspecFlow"/><section><span className="eyebrow">Trial encerrado</span><h1>Seu histórico está protegido por mais 7 dias.</h1><p>Contrate um plano para retomar a operação.</p><a className="primary link-button" href="mailto:contato@veross.com.br?subject=Plano ProspecFlow">Escolher plano</a><button className="text-button" onClick={signOut}>Sair da conta</button></section></div>;
  return <div data-theme={theme} className="app-shell">
    <header className="topbar"><a className="logo-button" href="/" onClick={e=>{e.preventDefault();setSection("central")}}><img src={theme==="dark"?DARK_LOGO:LIGHT_LOGO} alt="Veross ProspecFlow"/></a><nav><button className={section==="central"?"active":""} onClick={()=>setSection("central")}>Central</button><button className={section==="battle"?"active":""} onClick={()=>setSection("battle")}>Batalha</button><button className={["leads","setup","warroom"].includes(section)?"active":""} onClick={()=>setSection(can("manage_cadences")?"setup":"leads")}>COE</button></nav><div className="top-actions">{trialDay!==null&&<div className="trial-progress" title={`${trialDays} dias restantes`}><span>Trial · dia {trialDay} de 23</span><i><b style={{width:`${trialDay/23*100}%`}}/></i></div>}<button className="icon-button" onClick={toggleTheme}>{theme==="dark"?"☼":"◐"}</button><div className="profile-menu-wrap"><button className="avatar" onClick={()=>setUserMenu(v=>!v)} title="Abrir menu do usuário">{currentProfile?.first_name?.[0]||"V"}</button>{userMenu&&<div className="profile-menu"><div><b>{currentProfile?.first_name} {currentProfile?.last_name}</b><small>{currentProfile?.email}</small></div>{[["profile","Meu perfil"],["company","Empresa"],["users","Usuários e times"],["email","Configuração de e-mail"],["finance","Financeiro"]].map(([id,label])=><button key={id} onClick={()=>{setAccountTab(id);setModal("account");setUserMenu(false)}}>{label}</button>)}<button className="logout-button" onClick={signOut}>Sair da conta</button></div>}</div></div></header>
    {notice&&<button className="toast" onClick={()=>setNotice("")}>{notice}</button>}
    {section==="central"&&<Central leads={leads} activities={activities} profiles={profiles} settings={settings} overdue={overdue.length} onBattle={()=>setSection("battle")} onLead={openLead} onWar={()=>can("access_war_room")?setSection("warroom"):setNotice("Sua função não possui acesso à Sala de Guerra.")} onAll={()=>setSection("leads")}/>}
    {section==="battle"&&<Battle leads={leads} pending={battlePending} feedbackPrompt={settings.feedback_prompt} onLead={openLead} onFinish={finishActivity} onOpportunity={(id,activityId)=>post("setLeadStatus",{id,status:"won",activityId},"Lead marcado como ganho e atividade concluída.")} onLost={(id,activityId)=>{setSelectedLeadId(id);setOutcomeActivityId(activityId);setModal("lost")}} onChannel={openChannel}/>}
    {section==="setup"&&<OperationsNav section={section} setSection={setSection} canSetup={can("manage_cadences")} canWar={can("access_war_room")}><Setup cadences={cadences} activityTemplates={activityTemplates.filter(t=>t.type!=="meeting")} lossReasons={lossReasons} settings={settings} profiles={profiles} feedbackRequests={feedbackRequests} integrations={integrations} onNewCadence={()=>{setEditingCadence(null);setModal("cadence")}} onEditCadence={c=>{setEditingCadence(c);setModal("cadence")}} onToggleCadence={(id,active)=>post("toggleCadence",{id,active},active?"Cadência ativada.":"Cadência arquivada.")} onNewTemplate={()=>{setEditingTemplate(null);setModal("activityTemplate")}} onEditTemplate={t=>{setEditingTemplate(t);setModal("activityTemplate")}} onToggleTemplate={(id,active)=>post("toggleActivityTemplate",{id,active},active?"Atividade ativada.":"Atividade arquivada.")} onSaveSettings={s=>post("saveSettings",{settings:s},"Configuração salva.")} onAddLossReason={name=>post("createLossReason",{name},"Motivo adicionado.")} onToggleLossReason={(id,active)=>post("toggleLossReason",{id,active},"Motivo atualizado.")} onSaveIntegration={integration=>post(integration.id?"updateWebhookIntegration":"createWebhookIntegration",{integration},integration.id?"Integração atualizada.":"Integração criada. Copie o segredo agora.")} onToggleIntegration={(id,active)=>post("toggleWebhookIntegration",{id,active},active?"Integração ativada.":"Integração pausada.")} onRegenerateSecret={id=>post("regenerateWebhookSecret",{id},"Novo segredo gerado. Copie-o agora.")} onDeleteIntegration={id=>post("deleteWebhookIntegration",{id},"Integração excluída.")}/></OperationsNav>}
    {section==="leads"&&<OperationsNav section={section} setSection={setSection} canSetup={can("manage_cadences")} canWar={can("access_war_room")}><Leads leads={filteredLeads} cadences={cadences} search={search} setSearch={setSearch} statusFilter={statusFilter} setStatusFilter={setStatusFilter} cadenceFilter={cadenceFilter} setCadenceFilter={setCadenceFilter} onNew={can("create_leads")?()=>setModal("lead"):undefined} onImport={can("import_leads")?()=>setModal("import"):undefined} onImportHistory={can("import_leads")?()=>setModal("importHistory"):undefined} onLead={openLead} onDelete={can("delete_leads")?async lead=>{if(confirm(`Excluir permanentemente ${lead.first_name} ${lead.last_name} e todo o histórico?`))await post("deleteLead",{id:lead.id},"Lead e histórico excluídos.")}:undefined} onBulkDelete={can("delete_leads")?leadIds=>post("bulkDeleteLeads",{leadIds},`${leadIds.length} leads excluídos.`):undefined} onBulkCadence={(leadIds,cadenceId)=>post("bulkChangeCadence",{leadIds,cadenceId},"Cadência alterada para os leads selecionados.")}/></OperationsNav>}
    {section==="warroom"&&<OperationsNav section={section} setSection={setSection} canSetup={can("manage_cadences")} canWar={can("access_war_room")}><WarRoom leads={leads} activities={activities} profiles={profiles} lossReasons={lossReasons} settings={settings}/></OperationsNav>}
    {section==="lead"&&selectedLead&&<LeadDetail lead={selectedLead} feedbackRequest={feedbackRequests.find(f=>f.lead_id===selectedLead.id)} activities={activities.filter(a=>a.lead_id===selectedLead.id)} events={events.filter(e=>e.lead_id===selectedLead.id)} cadences={cadences} profiles={profiles.filter(p=>p.status==="active")} onBack={()=>setSection("leads")} onAdd={()=>setModal("activity")} onEdit={()=>setModal("editLead")} onComplete={(id)=>finishActivity("completeActivity",id)} onIgnore={id=>{setSelectedActivityId(id);setModal("ignore")}} onStatus={(status)=>{const activityId=activities.filter(a=>a.lead_id===selectedLead.id&&a.status==="pending").sort((a,b)=>+new Date(a.due_at)-+new Date(b.due_at))[0]?.id;return post("setLeadStatus",{id:selectedLead.id,status,activityId},`Status alterado para ${statusLabels[status]}.`)}} onLost={()=>{const activityId=activities.filter(a=>a.lead_id===selectedLead.id&&a.status==="pending").sort((a,b)=>+new Date(a.due_at)-+new Date(b.due_at))[0]?.id;setOutcomeActivityId(activityId||"");setModal("lost")}} onDelete={can("delete_leads")?async()=>{if(confirm(`Excluir permanentemente ${selectedLead.first_name} ${selectedLead.last_name} e todo o histórico?`)){const result=await post("deleteLead",{id:selectedLead.id},"Lead e histórico excluídos.");if(result){setSelectedLeadId("");setSection("leads")}}}:undefined} onChangeCadence={cadenceId=>post("changeCadence",{leadId:selectedLead.id,cadenceId},"Cadência alterada e atividades regeneradas.")} onChangeOwner={can("reassign_leads")?userId=>post("changeLeadOwner",{leadId:selectedLead.id,userId},"Responsável alterado."):undefined} onSaveObservations={observations=>post("updateLeadObservations",{id:selectedLead.id,observations},"Observações atualizadas.")} onPause={paused=>post("pauseCadence",{leadId:selectedLead.id,paused},paused?"Cadência pausada.":"Cadência retomada.")} onReopen={()=>setModal("reopen")}/>}

    {modal==="lead"&&<Modal title="Novo lead" close={()=>setModal(null)}><LeadForm cadences={cadences} customFields={settings.custom_fields} onSubmit={createLead}/></Modal>}
    {modal==="editLead"&&selectedLead&&<Modal title="Editar lead" close={()=>setModal(null)}><LeadForm lead={selectedLead} customFields={settings.custom_fields} onSubmit={updateLead}/></Modal>}
    {modal==="activity"&&selectedLead&&<Modal title="Nova atividade" close={()=>setModal(null)}><ActivityForm onSubmit={createActivity}/></Modal>}
    {modal==="ignore"&&selectedActivity&&<Modal title="Ignorar atividade" close={()=>setModal(null)}><form className="form" onSubmit={ignoreActivity}><p className="muted">A justificativa ficará registrada no histórico do lead.</p><label>Justificativa obrigatória<textarea name="notes" required minLength={3} placeholder="Explique por que esta atividade não será executada"/></label><button className="primary">Confirmar e ignorar</button></form></Modal>}
    {modal==="lost"&&selectedLead&&<Modal title="Marcar como perdido" close={()=>setModal(null)}><form className="form" onSubmit={loseLead}><label>Motivo da perda<select name="loss_reason_id" required><option value="">Selecione</option>{lossReasons.filter(r=>r.active).map(r=><option key={r.id} value={r.id}>{r.name}</option>)}</select></label><button className="primary danger">Confirmar perda</button></form></Modal>}
    {modal==="reopen"&&selectedLead&&<Modal title="Reabrir lead" close={()=>setModal(null)}><form className="form" onSubmit={reopenLead}><p className="muted">O histórico anterior será preservado e uma nova jornada será criada.</p><label>Nova cadência<select name="cadence_id" required defaultValue=""><option value="" disabled>Selecione</option>{cadences.filter(c=>c.active).map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label>{can("reassign_leads")&&<label>Responsável<select name="assigned_to" required defaultValue={selectedLead.created_by||currentProfile?.user_id||""}>{profiles.filter(p=>p.status==="active").map(p=><option key={p.user_id} value={p.user_id}>{p.first_name} {p.last_name}</option>)}</select></label>}<button className="primary">↩ Reabrir lead</button></form></Modal>}
    {modal==="import"&&<Modal title="Importar leads" close={()=>setModal(null)} wide><ImportForm cadences={cadences} profiles={profiles.filter(p=>p.status==="active")} customFields={settings.custom_fields} onImport={async(leads,cadenceId,assignedTo,fileName)=>{const r=await post("bulkCreateLeads",{leads,cadenceId,assignedTo,fileName});if(r){setNotice(`${r.created} leads importados e ${r.rejected} rejeitados. Consulte o histórico para ver os motivos.`);setModal(null)}}}/></Modal>}
    {modal==="importHistory"&&<Modal title="Histórico de importações" close={()=>setModal(null)} wide><ImportHistory imports={leadImports}/></Modal>}
    {modal==="cadence"&&<Modal title={editingCadence?"Editar cadência":"Nova cadência"} close={()=>setModal(null)} wide><CadenceForm initial={editingCadence} templates={activityTemplates.filter(t=>t.active&&t.type!=="meeting")} lossReasons={lossReasons} onSaveTemplate={template=>post(template.id?"updateActivityTemplate":"createActivityTemplate",{template},"Atividade salva na biblioteca.")} onSave={async cadence=>{if(await post(editingCadence?"updateCadence":"createCadence",{cadence},"Cadência salva."))setModal(null)}}/></Modal>}
    {modal==="activityTemplate"&&<Modal title={editingTemplate?"Editar atividade":"Criar atividade"} close={()=>setModal(null)}><ActivityTemplateForm initial={editingTemplate} onSave={async template=>{if(await post(editingTemplate?"updateActivityTemplate":"createActivityTemplate",{template},"Atividade salva na biblioteca.")){setModal("cadence");await loadData()}}}/></Modal>}
    {modal==="account"&&<Modal title="Conta e empresa" close={()=>setModal(null)} wide><AccountPanel tab={accountTab} setTab={setAccountTab} profile={currentProfile||undefined} profiles={profiles} invites={invites} organization={organization} settings={settings} onSaveProfile={async profile=>{if(await post("updateMyProfile",{profile},"Perfil atualizado."))setModal(null)}} onSaveCompany={name=>post("updateOrganization",{name},"Empresa atualizada.")} onSaveSettings={s=>post("saveSettings",{settings:s},"Configuração salva.")} onInvite={async u=>{const result=await post("inviteUser",{user:u});if(result)setNotice(result.emailSent?"Convite enviado por e-mail.":`Convite criado, mas o e-mail não foi enviado: ${result.emailError||"serviço de e-mail não configurado."}`);return result}} onResendInvite={async id=>{const result=await post("resendInvite",{id});if(result)setNotice("Convite reenviado por e-mail.")}} onUpdateUser={(userId,role,status)=>post("updateUser",{userId,role,status},"Usuário atualizado.")} onDeleteUser={userId=>post("deleteUser",{userId},"Usuário excluído.")} onCancelInvite={id=>post("cancelInvite",{id},"Convite cancelado.")}/></Modal>}
    {completionPrompt&&<div className="completion-ticker"><span><b>Atividade concluída</b> para {completionPrompt.leadName}. Deseja criar uma atividade extra?</span><button onClick={()=>{setSelectedLeadId(completionPrompt.leadId);setCompletionPrompt(null);setModal("activity")}}>Adicionar atividade extra</button><i><b/></i></div>}
  </div>;
}

function formLead(f:FormData,customFields:string[]){return{first_name:String(f.get("first_name")),last_name:String(f.get("last_name")||""),email:String(f.get("email")),phone:String(f.get("phone")||""),company:String(f.get("company")),job_title:String(f.get("job_title")||""),source:String(f.get("source")||"Manual"),custom_data:Object.fromEntries(customFields.map(field=>[field,String(f.get(`custom_${field}`)||"")]))}}
function PageHead({eyebrow,title,action}:{eyebrow:string;title:string;action?:React.ReactNode}){return <div className="page-head"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1></div>{action}</div>}
function Metric({label,value,progress}:{label:string;value:string;progress:number}){return <div className="metric"><span>{label}</span><strong>{value}</strong><i><b style={{width:`${Math.min(100,progress)}%`}}/></i></div>}
function sameMonth(value?:string|null){if(!value)return false;const d=new Date(value),n=new Date();return d.getMonth()===n.getMonth()&&d.getFullYear()===n.getFullYear()}
function isToday(value:string){const date=new Date(value),today=new Date();return date.getFullYear()===today.getFullYear()&&date.getMonth()===today.getMonth()&&date.getDate()===today.getDate()}
function calendarDayCount(start:Date,end:Date){const from=Date.UTC(start.getFullYear(),start.getMonth(),start.getDate()),to=Date.UTC(end.getFullYear(),end.getMonth(),end.getDate());return Math.max(1,Math.floor((to-from)/86400000)+1)}
function Central({leads,activities,profiles,settings,overdue,onBattle,onLead,onWar,onAll}:{leads:Lead[];activities:Activity[];profiles:Profile[];settings:OrganizationSettings;overdue:number;onBattle:()=>void;onLead:(id:string)=>void;onWar:()=>void;onAll:()=>void}){const pending=activities.filter(a=>a.status==="pending");return <main><PageHead eyebrow="Centro de informações de combate" title="Bom dia. Vamos avançar?"/><OperationsSnapshot leads={leads} activities={activities} profiles={profiles} settings={settings}/><div className="dashboard-grid"><aside className="stack"><section className="panel pad"><div className="row"><h2>Ritmo da semana</h2><button className="text-button" onClick={onWar}>Sala de Guerra →</button></div><Metric label="Atividades realizadas" value={String(activities.filter(a=>a.status==="completed").length)} progress={activities.length?activities.filter(a=>a.status==="completed").length/activities.length*100:0}/><Metric label="Leads ativos" value={String(leads.filter(l=>l.status==="prospecting").length)} progress={leads.length?leads.filter(l=>l.status==="prospecting").length/leads.length*100:0}/><Metric label="Ganhos" value={String(leads.filter(l=>l.status==="won").length)} progress={leads.length?leads.filter(l=>l.status==="won").length/leads.length*100:0}/></section></aside><section className="stack"><section className="mission"><div><span className="eyebrow">Missão do dia</span><h2>{pending.length} atividades para executar</h2><p>{overdue} atividades precisam de atenção agora.</p></div><strong>{pending.length}</strong><button className="primary" onClick={onBattle}>Entrar na Batalha →</button></section><section className="panel"><div className="panel-head"><h2>Próximas atividades</h2></div>{pending.slice(0,5).map(a=><ActivityRow key={a.id} activity={a} lead={leads.find(l=>l.id===a.lead_id)}/>)}</section></section><aside className="stack"><section className="panel pad"><div className="row"><h2>Novos alvos</h2><button className="text-button" onClick={onAll}>Ver todos</button></div>{leads.filter(l=>l.status!=="archived").slice(0,5).map(l=><button className="lead-mini" key={l.id} onClick={()=>onLead(l.id)}><span className="initials">{l.first_name[0]}{l.last_name[0]}</span><span><b>{l.first_name} {l.last_name}</b><small>{l.company}</small></span><strong>{l.score}</strong></button>)}</section><section className="panel pad"><h2>Radar</h2><p className="radar">Os leads com maior score aparecem primeiro na sua fila.</p></section></aside></div></main>}
function OperationsSnapshot({leads,activities,profiles,settings}:{leads:Lead[];activities:Activity[];profiles:Profile[];settings:OrganizationSettings}){const now=new Date(),year=now.getFullYear(),month=now.getMonth(),lastDay=new Date(year,month+1,0).getDate(),workDates=Array.from({length:lastDay},(_,i)=>new Date(year,month,i+1)).filter(d=>settings.work_days.includes(d.getDay())),elapsedWorkDays=workDates.filter(d=>d<=now).length,totalWorkDays=Math.max(1,workDates.length),finalized=leads.filter(l=>(l.status==="won"&&sameMonth(l.won_at))||(l.status==="lost"&&sameMonth(l.lost_at))),done=activities.filter(a=>a.status==="completed"&&sameMonth(a.completed_at)),gains=finalized.filter(l=>l.status==="won"),conversion=finalized.length?Math.round(gains.length/finalized.length*100):0,activityGoal=settings.daily_activity_goal*totalWorkDays,expectedGains=Math.round(settings.monthly_gain_goal*elapsedWorkDays/totalWorkDays),expectedActivities=settings.daily_activity_goal*elapsedWorkDays,people=profiles.filter(p=>p.status==="active"),countHint=(_current:number,expected:number,_label:string)=>`Previsto até hoje: ${expected}`,conversionHint=conversion>=settings.conversion_goal_pct?`Meta: ${settings.conversion_goal_pct}% · superada em ${(conversion-settings.conversion_goal_pct).toFixed(1)} p.p.`:`Meta: ${settings.conversion_goal_pct}% · faltam ${(settings.conversion_goal_pct-conversion).toFixed(1)} p.p.`;return <div className="operations-snapshot"><SnapshotCard icon="◎" title="Ganhos" value={gains.length} goal={settings.monthly_gain_goal} goalLabel="Meta do mês" progress={settings.monthly_gain_goal?gains.length/settings.monthly_gain_goal*100:0} tooltip={countHint(gains.length,expectedGains,"ganhos")} footer="ganhos por responsável">{people.map(p=>{const owned=leads.filter(l=>l.created_by===p.user_id),won=owned.filter(l=>l.status==="won"&&sameMonth(l.won_at));return <MiniPerson key={p.user_id} profile={p} left={owned.filter(l=>l.status==="prospecting").length} right={won.length}/>})}</SnapshotCard><SnapshotCard icon="✓" title="Atividades realizadas" value={done.length} goal={activityGoal} goalLabel="Meta do mês" progress={activityGoal?done.length/activityGoal*100:0} tooltip={countHint(done.length,expectedActivities,"atividades concluídas")} footer="realizadas por responsável">{people.map(p=><MiniPerson key={p.user_id} profile={p} right={done.filter(a=>a.assigned_to===p.user_id).length}/>)}</SnapshotCard><SnapshotCard icon="↗" title="Taxa de conversão" value={conversion} suffix="%" goal={settings.conversion_goal_pct} goalLabel="Meta de conversão" progress={settings.conversion_goal_pct?conversion/settings.conversion_goal_pct*100:0} tooltip={conversionHint} footer="ganhos por responsável">{people.map(p=>{const f=finalized.filter(l=>l.created_by===p.user_id),g=f.filter(l=>l.status==="won").length;return <MiniPerson key={p.user_id} profile={p} right={g} detail={f.length?`${Math.round(g/f.length*100)}%`:"0%"}/>})}</SnapshotCard></div>}
function SnapshotCard({icon,title,value,suffix="",goal,goalLabel,progress,tooltip,footer,children}:{icon:string;title:string;value:number;suffix?:string;goal:number;goalLabel:string;progress:number;tooltip:string;footer:string;children:React.ReactNode}){return <section className="panel snapshot-card"><h3>{title}</h3><span className="snapshot-icon">{icon}</span><strong>{value}{suffix}</strong><div className="snapshot-goal"><b tabIndex={0} className={`goal-hover ${progress>=100?"on-target":"below-target"}`}>{Math.round(progress)}% da meta<span className="goal-tooltip">{tooltip}</span></b><span>{goalLabel}: {goal}{suffix}</span></div><div className="snapshot-people">{children}</div><footer>{footer}</footer></section>}
function MiniPerson({profile,left,right,detail}:{profile:Profile;left?:number;right:number;detail?:string}){return <div className="mini-person"><span>{profile.first_name[0]}{profile.last_name?.[0]||""}</span><b>{profile.first_name}</b>{left!==undefined&&<small>{left} prospectando</small>}<strong>{right}{detail&&<em> ({detail})</em>}</strong></div>}
function ActivityRow({activity,lead}:{activity:Activity;lead?:Lead}){return <div className="activity-row"><span className="activity-icon">{activityIcons[activity.type]}</span><span><b>{activity.title}</b><small>{lead?`${lead.first_name} ${lead.last_name} · ${lead.company}`:"Lead"}</small></span><time>{new Date(activity.due_at).toLocaleString("pt-BR",{day:"2-digit",month:"2-digit",hour:"2-digit",minute:"2-digit"})}</time></div>}

function Battle({leads,pending,feedbackPrompt,onFinish,onLead,onOpportunity,onLost,onChannel}:{leads:Lead[];pending:Activity[];feedbackPrompt:string;onFinish:(a:"completeActivity"|"skipActivity",id:string,notes?:string)=>void;onLead:(id:string)=>void;onOpportunity:(id:string,activityId:string)=>void;onLost:(id:string,activityId:string)=>void;onChannel:(a:Activity,l?:Lead)=>void}){const [current,setCurrent]=useState(0);const [notes,setNotes]=useState("");const [skipError,setSkipError]=useState("");useEffect(()=>{if(current>=pending.length)setCurrent(Math.max(0,pending.length-1))},[pending.length,current]);const activity=pending[current];const lead=activity&&leads.find(l=>l.id===activity.lead_id),segment=lead?Object.entries(lead.custom_data||{}).find(([key])=>key.toLocaleLowerCase("pt-BR").includes("segmento"))?.[1]:undefined;if(!activity)return <main><PageHead eyebrow="Campo de batalha" title="Fila de execução"/><Empty title="Batalha concluída" text="Não há atividades programadas para hoje."/></main>;return <main><PageHead eyebrow="Campo de batalha" title="Fila de execução" action={<span className="muted">{pending.length} abertas hoje</span>}/><div className="battle-grid"><section className="panel queue"><h2>Agora</h2>{pending.map((a,i)=><button key={a.id} className={`${i===current?"active":""} ${!a.cadence_step_order?"extra-activity":""}`.trim()} onClick={()=>{setCurrent(i);setNotes("");setSkipError("")}}><small>{activityLabels[a.type]} <em className="step-label">{a.cadence_step_order?`Passo ${a.cadence_step_order}`:"Atividade extra"}</em></small><b>{leads.find(l=>l.id===a.lead_id)?.first_name} · {a.title}</b></button>)}</section><section className={`panel battle-card ${!activity.cadence_step_order?"extra-activity-card":""}`}><button className="text-button" onClick={()=>lead&&onLead(lead.id)}>Abrir ficha completa →</button><div className="activity-heading"><span className="eyebrow">{activityLabels[activity.type]}</span><span className="step-badge">{activity.cadence_step_order?`Passo ${activity.cadence_step_order}`:"Atividade extra"}</span></div><h2>{activity.title}</h2><h3>{lead?.first_name} {lead?.last_name} · {lead?.company}</h3><div className="script"><b>Objetivo da abordagem</b><p>{activity.notes||"Entender o cenário e combinar o próximo passo."}</p>{activity.type==="meeting"&&<p><b>Feedback:</b> {feedbackPrompt}</p>}</div><button className="secondary channel-action" onClick={()=>onChannel(activity,lead)}>Abrir canal</button><textarea value={notes} onChange={e=>{setNotes(e.target.value);if(e.target.value.trim())setSkipError("")}} placeholder="Registre o resultado ou justifique por que deseja ignorar"/>{skipError&&<small className="error-text">{skipError}</small>}<div className="button-row"><button className="primary" onClick={()=>onFinish("completeActivity",activity.id,notes)}>✓ Concluir</button><button className="secondary" onClick={()=>{if(!notes.trim()){setSkipError("Informe uma justificativa para ignorar esta atividade.");return}onFinish("skipActivity",activity.id,notes)}}>Ignorar</button><button className="secondary success-action" onClick={()=>lead&&onOpportunity(lead.id,activity.id)}>Ganho</button><button className="secondary loss-action" onClick={()=>lead&&onLost(lead.id,activity.id)}>Perdido</button></div></section><aside className="panel pad"><h2>Contexto</h2><Fact label="Nome" value={lead?`${lead.first_name} ${lead.last_name}`.trim():"—"}/><Fact label="Empresa" value={lead?.company||"—"}/><Fact label="Segmento" value={segment||"Não informado"}/><Fact label="E-mail" value={lead?.email||"—"}/><Fact label="Telefone" value={lead?.phone||"—"}/><Fact label="Cadência" value={lead?.cadence_name||"—"}/><Fact label="Score" value={`${lead?.score||0} pontos`}/></aside></div></main>}
function OperationsNav({section,setSection,children,canSetup,canWar}:{section:Section;setSection:(s:Section)=>void;children:React.ReactNode;canSetup:boolean;canWar:boolean}){return <main><PageHead eyebrow="Centro de operações" title="Controle da operação"/><div className="coe-grid"><aside className="panel side-nav">{canSetup&&<button className={section==="setup"?"active":""} onClick={()=>setSection("setup")}>Setup</button>}<button className={section==="leads"?"active":""} onClick={()=>setSection("leads")}>Leads</button>{canWar&&<button className={section==="warroom"?"active":""} onClick={()=>setSection("warroom")}>Sala de Guerra</button>}</aside>{children}</div></main>}

function Leads({leads,cadences,search,setSearch,statusFilter,setStatusFilter,cadenceFilter,setCadenceFilter,onNew,onImport,onImportHistory,onLead,onDelete,onBulkDelete,onBulkCadence}:{leads:Lead[];cadences:Cadence[];search:string;setSearch:(s:string)=>void;statusFilter:string;setStatusFilter:(s:string)=>void;cadenceFilter:string;setCadenceFilter:(s:string)=>void;onNew?:()=>void;onImport?:()=>void;onImportHistory?:()=>void;onLead:(id:string)=>void;onDelete?:(lead:Lead)=>void;onBulkDelete?:(ids:string[])=>Promise<unknown>;onBulkCadence:(ids:string[],cadenceId:string)=>void}){const [selected,setSelected]=useState<string[]>([]);const [bulkCadence,setBulkCadence]=useState("");const [importMenu,setImportMenu]=useState(false);return <section className="panel content"><div className="row"><div><h2>Leads</h2><p className="muted">Todo lead entra em uma cadência e fica sob responsabilidade de alguém do time.</p></div><div className="lead-actions">{onNew&&<button className="primary" onClick={onNew}>＋ Adicionar</button>}{(onImport||onImportHistory)&&<div className="import-menu"><button className="secondary" onClick={()=>setImportMenu(open=>!open)} aria-expanded={importMenu}>▧ Listas de importação⌄</button>{importMenu&&<div className="import-menu-popover">{onImport&&<button onClick={()=>{setImportMenu(false);onImport()}}><b>＋</b>Importar nova lista de leads</button>}{onImportHistory&&<button onClick={()=>{setImportMenu(false);onImportHistory()}}><b>⟲</b>Ver histórico</button>}</div>}</div>}</div></div><div className="filters"><input className="search" value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar por nome, empresa ou e-mail"/><select value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}><option value="active">Ativos</option><option value="all">Todos</option>{Object.entries(statusLabels).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select><select value={cadenceFilter} onChange={e=>setCadenceFilter(e.target.value)}><option value="">Todas as cadências</option>{cadences.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></div>{selected.length>0&&<div className="bulk-bar"><b>{selected.length} selecionados</b><select value={bulkCadence} onChange={e=>setBulkCadence(e.target.value)}><option value="">Nova cadência</option>{cadences.filter(c=>c.active).map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select><button className="small-button" disabled={!bulkCadence} onClick={()=>{onBulkCadence(selected,bulkCadence);setSelected([])}}>Aplicar em massa</button>{onBulkDelete&&<button className="small-button list-delete-action" onClick={async()=>{if(confirm(`Excluir ${selected.length} leads`)){const result=await onBulkDelete(selected);if(result)setSelected([])}}}>Excluir {selected.length}</button>}</div>}<div className="table-wrap"><table><thead><tr><th><input type="checkbox" checked={leads.length>0&&selected.length===leads.length} onChange={e=>setSelected(e.target.checked?leads.map(l=>l.id):[])}/></th><th>Lead</th><th>Empresa</th><th>Cadência</th><th>Score</th><th>Status</th><th>Origem</th>{onDelete&&<th>Ações</th>}</tr></thead><tbody>{leads.map(l=><tr key={l.id}><td><input type="checkbox" checked={selected.includes(l.id)} onChange={e=>setSelected(x=>e.target.checked?[...x,l.id]:x.filter(id=>id!==l.id))}/></td><td onClick={()=>onLead(l.id)}><b>{l.first_name} {l.last_name}</b><small>{l.email}</small></td><td onClick={()=>onLead(l.id)}>{l.company}</td><td>{l.cadence_name||"—"}</td><td className="score">{l.score}</td><td><span className={`pill status-${l.status}`}>{statusLabels[l.status]}</span></td><td>{l.source}</td>{onDelete&&<td><button className="small-button list-delete-action" onClick={()=>onDelete(l)}>Excluir</button></td>}</tr>)}</tbody></table></div></section>}
type WarPeriod="today"|"week"|"month"|"lastMonth"|"quarter"|"semester"|"year"|"custom";
function warRange(period:WarPeriod,customStart:string,customEnd:string){const now=new Date(),start=new Date(now),end=new Date(now);start.setHours(0,0,0,0);end.setHours(23,59,59,999);let label="Hoje";if(period==="week"){start.setDate(now.getDate()-((now.getDay()+6)%7));end.setTime(start.getTime());end.setDate(start.getDate()+6);end.setHours(23,59,59,999);label="Esta semana"}if(period==="month"){start.setDate(1);end.setFullYear(now.getFullYear(),now.getMonth()+1,0);end.setHours(23,59,59,999);label="Este mês"}if(period==="lastMonth"){start.setFullYear(now.getFullYear(),now.getMonth()-1,1);end.setFullYear(now.getFullYear(),now.getMonth(),0);end.setHours(23,59,59,999);label="Mês passado"}if(period==="quarter"){const firstMonth=Math.floor(now.getMonth()/3)*3;start.setMonth(firstMonth,1);end.setFullYear(now.getFullYear(),firstMonth+3,0);end.setHours(23,59,59,999);label="Este trimestre"}if(period==="semester"){const firstMonth=now.getMonth()<6?0:6;start.setMonth(firstMonth,1);end.setFullYear(now.getFullYear(),firstMonth+6,0);end.setHours(23,59,59,999);label="Este semestre"}if(period==="year"){start.setMonth(0,1);end.setFullYear(now.getFullYear(),11,31);end.setHours(23,59,59,999);label="Este ano"}if(period==="custom"){if(customStart)start.setTime(new Date(customStart+"T00:00:00").getTime());if(customEnd)end.setTime(new Date(customEnd+"T23:59:59").getTime());label=customStart&&customEnd?new Date(customStart+"T12:00:00").toLocaleDateString("pt-BR")+" a "+new Date(customEnd+"T12:00:00").toLocaleDateString("pt-BR"):"Data personalizada"}return{start,end,label}}
function within(value:string|null|undefined,start:Date,end:Date){if(!value)return false;const date=new Date(value);return date>=start&&date<=end}
function WarRoom({leads,activities,profiles,lossReasons,settings}:{leads:Lead[];activities:Activity[];profiles:Profile[];lossReasons:LossReason[];settings:OrganizationSettings}){const now=new Date(),today=now.toISOString().slice(0,10),monthStart=new Date(now.getFullYear(),now.getMonth(),1).toISOString().slice(0,10),[period,setPeriod]=useState<WarPeriod>("month"),[customStart,setCustomStart]=useState(monthStart),[customEnd,setCustomEnd]=useState(today),range=warRange(period,customStart,customEnd),done=activities.filter(a=>a.status==="completed"&&within(a.completed_at,range.start,range.end)),finalized=leads.filter(l=>(l.status==="won"&&within(l.won_at,range.start,range.end))||(l.status==="lost"&&within(l.lost_at,range.start,range.end))),gains=finalized.filter(l=>l.status==="won"),conversion=finalized.length?gains.length/finalized.length*100:0,meetings=done.filter(a=>a.type==="meeting").length,days=calendarDayCount(range.start,range.end),workDays=Array.from({length:days},(_,i)=>{const d=new Date(range.start);d.setDate(d.getDate()+i);return d.getDay()}).filter(d=>settings.work_days.includes(d)).length,activityGoal=settings.daily_activity_goal*workDays,gainGoal=Math.max(1,Math.round(settings.monthly_gain_goal*days/30.44)),meetingGoal=Math.max(1,Math.round(settings.meeting_goal*days/7));return <section className="content war-room"><div className="war-period"><div><span className="eyebrow">Período analisado</span><h2>{range.label}</h2></div><select value={period} onChange={e=>setPeriod(e.target.value as WarPeriod)}><option value="today">Hoje</option><option value="week">Esta semana</option><option value="month">Este mês</option><option value="lastMonth">Mês passado</option><option value="quarter">Este trimestre</option><option value="semester">Este semestre</option><option value="year">Este ano</option><option value="custom">Data personalizada</option></select>{period==="custom"&&<div className="custom-period"><label>Início<input type="date" value={customStart} onChange={e=>setCustomStart(e.target.value)}/></label><label>Fim<input type="date" min={customStart} value={customEnd} onChange={e=>setCustomEnd(e.target.value)}/></label></div>}</div><div className="war-grid"><GoalStat label="Atividades no período" value={done.length} goal={activityGoal}/><GoalStat label="Leads finalizados" value={finalized.length} goal={gainGoal}/><GoalStat label="Conversão em ganho" value={Math.round(conversion)} goal={settings.conversion_goal_pct} suffix="%"/><GoalStat label="Reuniões no período" value={meetings} goal={meetingGoal}/></div><GainTrendChart gains={gains} goal={gainGoal} start={range.start} end={range.end} label={range.label} period={period}/><ActivityPeriodChart activities={activities} start={range.start} end={range.end} period={period} settings={settings}/><div className="analysis-grid"><LossReasonChart leads={finalized} reasons={lossReasons}/><OriginConversion leads={finalized}/></div><ResponseTime leads={leads.filter(l=>within(l.created_at,range.start,range.end))} activities={activities} profiles={profiles}/></section>}
type TrendBucket={label:string;detail:string;start:Date;end:Date};
function gainTrendBuckets(start:Date,end:Date,period:WarPeriod){const days=calendarDayCount(start,end),daily=period==="today"||period==="week"||period==="month"||period==="lastMonth"||(period==="custom"&&days<=31),monthly=period==="quarter"||period==="semester"||period==="year"||(period==="custom"&&days>120),buckets:TrendBucket[]=[];if(daily){for(let i=0;i<days;i++){const from=new Date(start);from.setDate(from.getDate()+i);const to=new Date(from);to.setHours(23,59,59,999);buckets.push({label:period==="week"?from.toLocaleDateString("pt-BR",{weekday:"short",day:"2-digit"}).replace(".",""):period==="month"||period==="lastMonth"?String(from.getDate()):from.toLocaleDateString("pt-BR",{day:"2-digit",month:"2-digit"}),detail:from.toLocaleDateString("pt-BR"),start:from,end:to})}}else if(monthly){const cursor=new Date(start.getFullYear(),start.getMonth(),1);while(cursor<=end){const from=new Date(cursor),to=new Date(cursor.getFullYear(),cursor.getMonth()+1,0,23,59,59,999);buckets.push({label:from.toLocaleDateString("pt-BR",{month:"short"}).replace(".",""),detail:from.toLocaleDateString("pt-BR",{month:"long",year:"numeric"}),start:from,end:to>end?new Date(end):to});cursor.setMonth(cursor.getMonth()+1)}}else{let cursor=new Date(start),index=1;while(cursor<=end){const from=new Date(cursor),to=new Date(cursor);to.setDate(to.getDate()+6);to.setHours(23,59,59,999);buckets.push({label:`Sem. ${index++}`,detail:`${from.toLocaleDateString("pt-BR")} a ${new Date(Math.min(+to,+end)).toLocaleDateString("pt-BR")}`,start:from,end:to>end?new Date(end):to});cursor.setDate(cursor.getDate()+7)}}return buckets}
