function ActivityPeriodChart({activities,start,end,period,settings}:{activities:Activity[];start:Date;end:Date;period:WarPeriod;settings:OrganizationSettings}){type Bucket={label:string;start:Date;end:Date};type Series="goal"|"completed"|"skipped";const [visible,setVisible]=useState<Record<Series,boolean>>({goal:true,completed:true,skipped:true}),days=calendarDayCount(start,end),daily=period==="today"||period==="week"||period==="month"||period==="lastMonth"||(period==="custom"&&days<=31),monthly=period==="quarter"||period==="semester"||period==="year"||(period==="custom"&&days>120);let buckets:Bucket[]=[];if(period==="today"){buckets=[{label:"Hoje",start:new Date(start),end:new Date(end)}]}else if(daily){for(let i=0;i<days;i++){const from=new Date(start);from.setDate(from.getDate()+i);const to=new Date(from);to.setHours(23,59,59,999);buckets.push({label:period==="week"?from.toLocaleDateString("pt-BR",{weekday:"short",day:"2-digit"}).replace(".",""):period==="month"||period==="lastMonth"?String(from.getDate()).padStart(2,"0"):from.toLocaleDateString("pt-BR",{day:"2-digit",month:"2-digit"}),start:from,end:to})}}else if(monthly){const cursor=new Date(start.getFullYear(),start.getMonth(),1);while(cursor<=end){const from=new Date(cursor),to=new Date(cursor.getFullYear(),cursor.getMonth()+1,0,23,59,59,999);buckets.push({label:cursor.toLocaleDateString("pt-BR",{month:"short"}).replace(".",""),start:from,end:to>end?new Date(end):to});cursor.setMonth(cursor.getMonth()+1)}}else{let cursor=new Date(start);let n=1;while(cursor<=end){const from=new Date(cursor),to=new Date(cursor);to.setDate(to.getDate()+6);to.setHours(23,59,59,999);buckets.push({label:`Sem. ${n++}`,start:from,end:to>end?new Date(end):to});cursor.setDate(cursor.getDate()+7)}}const resolvedAt=(a:Activity)=>a.completed_at||(a.status==="skipped"?a.updated_at:null),data=buckets.map(b=>{const bucketDays=calendarDayCount(b.start,b.end),workDays=Array.from({length:bucketDays},(_,i)=>{const d=new Date(b.start);d.setDate(d.getDate()+i);return d}).filter(d=>d<=end&&settings.work_days.includes(d.getDay())).length;return {goal:settings.daily_activity_goal*workDays,completed:activities.filter(a=>a.status==="completed"&&within(resolvedAt(a),b.start,b.end)).length,skipped:activities.filter(a=>a.status==="skipped"&&within(resolvedAt(a),b.start,b.end)).length}}),activeValues=data.flatMap(d=>(Object.keys(visible) as Series[]).filter(key=>visible[key]).map(key=>d[key])),max=Math.max(1,...activeValues),toggle=(key:Series)=>setVisible(current=>({...current,[key]:!current[key]})),series:[Series,string][]=[["goal","Meta"],["completed","Realizado"],["skipped","Ignorado"]];return <section className="panel period-chart"><div className="period-chart-head"><h2>Atividades concluídas</h2><div className="period-legend">{series.map(([key,label])=><button key={key} type="button" className={`${key} ${visible[key]?"active":"inactive"}`} aria-pressed={visible[key]} onClick={()=>toggle(key)}><i/>{label}</button>)}</div></div><div className="period-bars">{buckets.map((b,i)=><div className="period-bar" key={b.label+i}><div className="period-columns">{series.map(([key,label])=>visible[key]&&<div className={`period-column ${key}`} key={key} title={`${label}: ${data[i][key]}`} style={{height:Math.max(data[i][key]?8:2,data[i][key]/max*100)+"%"}}><strong>{data[i][key]}</strong></div>)}</div><span>{b.label}</span></div>)}</div></section>}
function LossReasonChart({leads,reasons}:{leads:Lead[];reasons:LossReason[]}){const lost=leads.filter(l=>l.status==="lost"),counts=reasons.map(r=>({name:r.name,count:lost.filter(l=>l.loss_reason_id===r.id).length})).filter(x=>x.count).sort((a,b)=>b.count-a.count);return <section className="panel horizontal-chart"><h2>Motivos de perda</h2>{counts.map(x=>{const pct=lost.length?Math.round(x.count/lost.length*100):0;return <div className="horizontal-row" key={x.name}><span>{x.name}</span><i><b className="loss-fill" style={{width:pct+"%"}}/></i><strong>{pct}%</strong></div>})}{!counts.length&&<p className="muted empty-analysis">Nenhuma perda registrada no período.</p>}</section>}
