function GoalStat({label,value,goal,suffix=""}:{label:string;value:number;goal:number;suffix?:string}){const pct=goal?Math.min(100,value/goal*100):0;return <div className="panel stat goal-stat"><span>{label}</span><strong>{value}{suffix}</strong><small>Meta: {goal}{suffix}</small><i><b style={{width:`${pct}%`}}/></i></div>}
function Stat({label,value}:{label:string;value:string}){return <div className="panel stat"><span>{label}</span><strong>{value}</strong></div>}

function LeadDetail({lead,feedbackRequest,activities,events,cadences,profiles,onBack,onAdd,onEdit,onComplete,onIgnore,onStatus,onLost,onDelete,onChangeCadence,onChangeOwner,onSaveObservations,onPause,onReopen}:{lead:Lead;feedbackRequest?:FeedbackRequest;activities:Activity[];events:LeadEvent[];cadences:Cadence[];profiles:Profile[];onBack:()=>void;onAdd:()=>void;onEdit:()=>void;onComplete:(id:string)=>void;onIgnore:(id:string)=>void;onStatus:(s:LeadStatus)=>void;onLost:()=>void;onDelete?:()=>void;onChangeCadence:(id:string)=>void;onChangeOwner?:(id:string)=>void;onSaveObservations:(observations:string)=>void;onPause:(p:boolean)=>void;onReopen:()=>void}){
  const [observations,setObservations]=useState(lead.observations||"");
  const [historyOpen,setHistoryOpen]=useState(false);
  useEffect(()=>{setObservations(lead.observations||"");setHistoryOpen(false)},[lead.id,lead.observations]);
  const isFinal=lead.status==="won"||lead.status==="lost";
  const latestJourney=Math.max(1,...activities.map(activity=>Number(activity.journey_number)||1));
  const activeActivities=activities.filter(activity=>(Number(activity.journey_number)||1)===latestJourney);
  const historicalActivities=activities.filter(activity=>(Number(activity.journey_number)||1)!==latestJourney);
  const journeyStartedAt=activeActivities.map(activity=>activity.created_at).filter(Boolean).sort()[0];
  const activeEvents=journeyStartedAt?events.filter(event=>event.created_at>=journeyStartedAt):events;
  const historicalEvents=journeyStartedAt?events.filter(event=>event.created_at<journeyStartedAt):[];
  const activityTimestamp=(activity:Activity)=>activity.status==="pending"?activity.due_at:activity.completed_at||activity.updated_at||activity.due_at;
  const renderActivity=(activity:Activity)=><article key={activity.id} className={activity.status==="completed"?"done":""}><span>{activity.status==="completed"?"✓":activityIcons[activity.type]}</span><div><div className="row"><h3>{activity.title}</h3><time>{new Date(activityTimestamp(activity)).toLocaleString("pt-BR")}</time></div><p>{activity.notes||"Nenhuma anotação."}</p><small className="muted">{activityLabels[activity.type]} · {activity.status}</small>{activity.status==="pending"&&!isFinal&&<div className="button-row timeline-actions"><button className="small-button" onClick={()=>onComplete(activity.id)}>Concluir</button><button className="small-button" onClick={()=>onIgnore(activity.id)}>Ignorar</button></div>}</div></article>;
  const renderEvent=(event:LeadEvent)=><article key={event.id} className="event"><span>•</span><div><div className="row"><h3>{event.title}</h3><time>{new Date(event.created_at).toLocaleString("pt-BR")}</time></div><p>{event.body}</p></div></article>;
  const hasHistory=historicalActivities.length>0||historicalEvents.length>0;
  return <main><PageHead eyebrow="Ficha do lead" title={`${lead.first_name} ${lead.last_name}`} action={<div className="button-row"><button className="secondary" onClick={onEdit}>Editar dados</button>{isFinal?<><span className={`lead-outcome ${lead.status}`}><b>{lead.status==="won"?"✓":"×"}</b>{statusLabels[lead.status]}</span><button className="secondary reopen-action" title="Reabrir lead" aria-label="Reabrir lead" onClick={onReopen}>↩</button></>:<><button className="primary success-action" onClick={()=>onStatus("won")}>Ganho</button><button className="secondary loss-action" onClick={onLost}>Perdido</button></>}</div>}/><button className="back" onClick={onBack}>← Voltar para leads</button><section className="panel lead-observations"><div><h2>Anotações</h2><p className="muted">Notas gerais sobre o lead, independentes das atividades da cadência.</p></div><textarea value={observations} onChange={e=>setObservations(e.target.value)} placeholder="Registre contexto, decisões, próximos passos ou pontos de atenção."/><div className="button-row"><button className="primary" onClick={()=>onSaveObservations(observations)}>Salvar anotações</button></div></section><div className="lead-grid"><aside className="panel pad lead-profile"><span className="initials big">{lead.first_name[0]}{lead.last_name[0]}</span><h2>{lead.company}</h2><p className="muted">{lead.job_title||"Cargo não informado"}</p><div className="mini-stats"><Stat label="Feitas" value={String(activities.filter(activity=>activity.status==="completed").length)}/><Stat label="Abertas" value={String(activities.filter(activity=>activity.status==="pending").length)}/></div><Fact label="Status" value={statusLabels[lead.status]}/><Fact label="E-mail" value={lead.email}/><Fact label="Telefone" value={lead.phone||"—"}/><Fact label="Score Lead" value={`${lead.score} pontos`}/>{feedbackRequest&&<div className="feedback-link-card"><small>Feedback do ganho</small><b>{feedbackRequest.status==="responded"?"Respondido":"Aguardando resposta"}</b><button className="small-button" onClick={async()=>{await navigator.clipboard.writeText(`${window.location.origin}/feedback/${feedbackRequest.token}`)}}>Copiar link exclusivo</button></div>}{Object.entries(lead.custom_data||{}).map(([key,value])=><Fact key={key} label={key} value={value||"—"}/>)}<label className="inline-field">Cadência<select value={lead.cadence_id||""} disabled={isFinal} onChange={event=>onChangeCadence(event.target.value)}>{cadences.filter(cadence=>cadence.active).map(cadence=><option key={cadence.id} value={cadence.id}>{cadence.name}</option>)}</select></label>{onChangeOwner&&<label className="inline-field">Responsável<select value={lead.created_by||""} disabled={isFinal} onChange={event=>onChangeOwner(event.target.value)}><option value="" disabled>Selecione</option>{profiles.map(profile=><option key={profile.user_id} value={profile.user_id}>{profile.first_name} {profile.last_name}</option>)}</select></label>}<div className="button-stack">{!isFinal&&<><button className="secondary" onClick={()=>onPause(lead.cadence_status!=="paused")}>{lead.cadence_status==="paused"?"Retomar cadência":"Pausar cadência"}</button><button className="secondary" onClick={()=>onStatus("archived")}>Arquivar lead</button></>}{onDelete&&<button className="secondary delete-lead-action" onClick={onDelete}>Excluir lead permanentemente</button>}</div></aside><section className="panel timeline-panel"><div className="row"><div><h2>Jornada de prospecção</h2><p className="muted">{isFinal?"Jornada encerrada. Reabra o lead para iniciar uma nova cadência.":"Execução e histórico da jornada atual."}</p></div>{!isFinal&&<button className="secondary" onClick={onAdd}>+ Atividade</button>}</div><div className="timeline">{activeActivities.map(renderActivity)}{activeEvents.map(renderEvent)}{!activeActivities.length&&!activeEvents.length&&<Empty title="Sem jornada ativa" text="Reabra o lead para começar uma nova cadência."/>}</div>{hasHistory&&<section className="journey-history"><button className="history-toggle" onClick={()=>setHistoryOpen(open=>!open)} aria-expanded={historyOpen}>▸ Histórico da jornada anterior ({historicalActivities.length} atividades){historyOpen?" — ocultar":" — visualizar"}</button>{historyOpen&&<div className="timeline history-timeline">{historicalActivities.map(renderActivity)}{historicalEvents.map(renderEvent)}</div>}</section>}</section></div></main>
}function Fact({label,value}:{label:string;value:string}){const normalized=label.toLocaleLowerCase("pt-BR");const isLink=/site|website|linkedin|instagram/.test(normalized)&&Boolean(value)&&value!=="—";const href=value.startsWith("http")?value:`https://${value}`;return <div className="fact"><span>{label}</span>{isLink?<a href={href} target="_blank" rel="noopener noreferrer">{value}</a>:<b>{value}</b>}</div>}

function Setup({cadences,activityTemplates,lossReasons,settings,profiles,feedbackRequests,integrations,onNewCadence,onEditCadence,onToggleCadence,onNewTemplate,onEditTemplate,onToggleTemplate,onSaveSettings,onAddLossReason,onToggleLossReason,onSaveIntegration,onToggleIntegration,onRegenerateSecret,onDeleteIntegration}:{cadences:Cadence[];activityTemplates:ActivityTemplate[];lossReasons:LossReason[];settings:OrganizationSettings;profiles:Profile[];feedbackRequests:FeedbackRequest[];integrations:WebhookIntegration[];onNewCadence:()=>void;onEditCadence:(c:Cadence)=>void;onToggleCadence:(id:string,a:boolean)=>void;onNewTemplate:()=>void;onEditTemplate:(t:ActivityTemplate)=>void;onToggleTemplate:(id:string,a:boolean)=>void;onSaveSettings:(s:OrganizationSettings)=>void;onAddLossReason:(n:string)=>void;onToggleLossReason:(id:string,a:boolean)=>void;onSaveIntegration:(integration:Partial<WebhookIntegration>)=>Promise<Record<string,unknown>|null>;onToggleIntegration:(id:string,active:boolean)=>Promise<Record<string,unknown>|null>;onRegenerateSecret:(id:string)=>Promise<Record<string,unknown>|null>;onDeleteIntegration:(id:string)=>Promise<Record<string,unknown>|null>}){
  const [tab,setTab]=useState("Início");
  const cards=[["Cadências",`${cadences.length} configuradas`],["Atividades",`${activityTemplates.length} na biblioteca`],["Integrações",`${integrations.length} configurada(s)`],["Metas","Objetivos do time"],["Motivos de perda","Padronize encerramentos"],["Calendário","Dias e horários"],["Campos dos leads","Dados personalizados"],["Score Lead","Regras de prioridade"],["Feedback","Qualidade das reuniões"],["Blocklist","Domínios e contatos"],["Permissões","Acesso por função"]];
  return <section className="panel content"><div className="row"><div><h2>{tab==="Início"?"Setup":`Setup · ${tab}`}</h2><p className="muted">Crie atividades primeiro e depois use-as nas cadências.</p></div>{tab!=="Início"&&<button className="text-button" onClick={()=>setTab("Início")}>← Voltar ao Setup</button>}</div>
    {tab==="Início"?<div className="setup-grid">{cards.map(([a,b])=><button key={a} onClick={()=>setTab(a)}><span>◇</span><b>{a}</b><small>{b}</small></button>)}</div>
    :tab==="Cadências"?<CadenceDirectory cadences={cadences} onNew={onNewCadence} onEdit={onEditCadence} onToggle={onToggleCadence}/>
    :tab==="Atividades"?<div className="config-list"><div className="row"><div><h2>Biblioteca de atividades</h2><small>Nome, canal, instrução e template ficam reutilizáveis.</small></div><button className="primary" onClick={onNewTemplate}>+ Criar atividade</button></div>{activityTemplates.map(t=><article key={t.id}><div className="template-name"><span className="activity-icon">{activityIcons[t.type]}</span><div><b>{t.name}</b><small>{activityLabels[t.type]} · {t.instructions||"Sem instrução"}</small></div></div><div className="button-row"><button className="small-button" onClick={()=>onEditTemplate(t)}>Editar</button><button className="small-button" onClick={()=>onToggleTemplate(t.id,!t.active)}>{t.active?"Arquivar":"Ativar"}</button></div></article>)}</div>
    :tab==="Integrações"?<Integrations cadences={cadences} profiles={profiles} integrations={integrations} onSave={onSaveIntegration} onToggle={onToggleIntegration} onRegenerateSecret={onRegenerateSecret} onDelete={onDeleteIntegration}/>
    :tab==="Motivos de perda"?<LossReasons reasons={lossReasons} onAdd={onAddLossReason} onToggle={onToggleLossReason}/>
    :tab==="Permissões"?<PermissionSettings settings={settings} onSave={onSaveSettings}/>:tab==="Feedback"?<FeedbackDashboard requests={feedbackRequests} cadences={cadences} profiles={profiles}/>
    :<SettingsForm mode={tab} settings={settings} onSave={onSaveSettings}/>}</section>
}
function Integrations({cadences,profiles,integrations,onSave,onToggle,onRegenerateSecret,onDelete}:{cadences:Cadence[];profiles:Profile[];integrations:WebhookIntegration[];onSave:(integration:Partial<WebhookIntegration>)=>Promise<Record<string,unknown>|null>;onToggle:(id:string,active:boolean)=>Promise<Record<string,unknown>|null>;onRegenerateSecret:(id:string)=>Promise<Record<string,unknown>|null>;onDelete:(id:string)=>Promise<Record<string,unknown>|null>}){const [editing,setEditing]=useState<WebhookIntegration|null|undefined>(undefined);const [credentials,setCredentials]=useState<{endpoint:string;secret:string}|null>(null);const endpointFor=(key:string)=>`${typeof window==="undefined"?"":window.location.origin}/api/webhooks/alessia-flow/${key}`;const copy=(value:string)=>void navigator.clipboard.writeText(value);async function save(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=new FormData(event.currentTarget),draft={id:editing?.id,name:String(form.get("name")||""),cadence_id:String(form.get("cadence_id")||""),assigned_to:String(form.get("assigned_to")||""),active:editing?.active??true};const result=await onSave(draft);if(!result)return;const data=result.data as {webhook_key?:string}|undefined,secret=String(result.secret||"");if(secret&&data?.webhook_key){setCredentials({endpoint:endpointFor(data.webhook_key),secret});setEditing(undefined)}else setEditing(undefined)}async function regenerate(integration:WebhookIntegration){if(!confirm(`Gerar um novo segredo para ${integration.name}? O n8n atual deixará de funcionar até ser atualizado.`))return;const result=await onRegenerateSecret(integration.id),data=result?.data as {webhook_key?:string}|undefined,secret=String(result?.secret||"");if(secret&&data?.webhook_key)setCredentials({endpoint:endpointFor(data.webhook_key),secret})}async function remove(integration:WebhookIntegration){if(!confirm(`Excluir a integração “${integration.name}”? O histórico de eventos dela será removido. Os leads já criados permanecerão.`))return;await onDelete(integration.id)}return <div className="integrations"><div className="row"><div><h2>Integrações</h2><p className="muted">Cada integração possui URL, segredo, cadência e responsável próprios.</p></div><button className="primary" onClick={()=>setEditing(null)}>+ Nova integração</button></div>{credentials&&<section className="integration-credentials"><div><h3>Configure o n8n agora</h3><p>O segredo só é exibido neste momento. Copie os dois valores antes de fechar.</p></div><label>URL do webhook<input readOnly value={credentials.endpoint}/><button className="small-button" onClick={()=>copy(credentials.endpoint)}>Copiar URL</button></label><label>Segredo<input readOnly value={credentials.secret}/><button className="small-button" onClick={()=>copy(credentials.secret)}>Copiar segredo</button></label><button className="text-button" onClick={()=>setCredentials(null)}>Fechar</button></section>}{editing!==undefined&&<section className="integration-form"><div className="row"><h3>{editing?"Editar integração":"Nova integração AlessIA Flow"}</h3><button className="text-button" onClick={()=>setEditing(undefined)}>Cancelar</button></div><form className="form" onSubmit={save}><label>Nome da integração<input name="name" required defaultValue={editing?.name||"AlessIA Flow"} placeholder="Ex.: AlessIA · Prospecção LinkedIn"/></label><label>Cadência de destino<select name="cadence_id" required defaultValue={editing?.cadence_id||""}><option value="" disabled>Selecione a cadência</option>{cadences.filter(c=>c.active).map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label>Responsável padrão<select name="assigned_to" required defaultValue={editing?.assigned_to||""}><option value="" disabled>Selecione o responsável</option>{profiles.filter(p=>p.status==="active").map(p=><option key={p.user_id} value={p.user_id}>{p.first_name} {p.last_name}</option>)}</select></label><p className="notice">O lead recebido será criado nesta cadência, atribuído a este responsável e iniciará a primeira atividade automaticamente.</p><button className="primary">{editing?"Salvar integração":"Criar integração"}</button></form></section>}<div className="integration-list">{integrations.map(integration=><article key={integration.id}><div><span className={`pill ${integration.active?"status-prospecting":"status-archived"}`}>{integration.active?"Ativa":"Inativa"}</span><h3>{integration.name}</h3><p>{integration.cadence_name} · {integration.responsible_name}</p><small>{integration.created_count} leads criados em {integration.event_count} evento(s){integration.last_received_at?` · Último: ${new Date(integration.last_received_at).toLocaleString("pt-BR")}`:""}</small></div><div className="button-row"><button className="small-button" onClick={()=>setEditing(integration)}>Editar</button><button className="small-button" onClick={()=>void regenerate(integration)}>Novo segredo</button><button className="small-button" onClick={()=>void onToggle(integration.id,!integration.active)}>{integration.active?"Pausar":"Ativar"}</button><button className="small-button list-delete-action" onClick={()=>void remove(integration)}>Excluir</button></div></article>)}</div>{!integrations.length&&editing===undefined&&<Empty title="Nenhuma integração criada" text="Crie uma integração para receber leads da AlessIA Flow."/>}</div>}
function CadenceDirectory({cadences,onNew,onEdit,onToggle}:{cadences:Cadence[];onNew:()=>void;onEdit:(cadence:Cadence)=>void;onToggle:(id:string,active:boolean)=>void}){const [search,setSearch]=useState("");const [status,setStatus]=useState("active");const focusLabels:Record<string,string>={inbound_active:"Inbound ativo",inbound_passive:"Inbound passivo",outbound:"Outbound",other:"Outro"};const visible=cadences.filter(cadence=>(status==="all"||status==="active"?cadence.active:!cadence.active)&&`${cadence.name} ${cadence.description||""} ${focusLabels[cadence.focus||"outbound"]}`.toLocaleLowerCase("pt-BR").includes(search.toLocaleLowerCase("pt-BR")));return <div className="cadence-directory"><div className="row"><div><h2>Cadências</h2><p className="muted">Defina, acompanhe e ajuste as sequências usadas pelo time.</p></div><button className="primary" onClick={onNew}>+ Criar cadência</button></div><div className="cadence-filters"><select value={status} onChange={e=>setStatus(e.target.value)}><option value="active">Ativas</option><option value="archived">Arquivadas</option><option value="all">Todas</option></select><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Pesquisar por nome"/></div><p className="muted"><b>{visible.length}</b> cadência(s) exibida(s).</p><div className="table-wrap"><table className="cadence-table"><thead><tr><th>Prioridade</th><th>Nome da cadência</th><th>Foco</th><th>Total</th><th>Aguardando início</th><th>Em execução</th><th>Finalizados</th><th>Ganhos</th><th>Ações</th></tr></thead><tbody>{visible.map(cadence=><tr key={cadence.id}><td><span className={`priority-mark ${cadence.priority||"normal"}`}>{cadence.priority==="high"?"↑":cadence.priority==="low"?"↓":"•"}</span></td><td><button className="cadence-name" onClick={()=>onEdit(cadence)}><b>{cadence.name}</b><small>{cadence.steps.length} atividades{cadence.description?` · ${cadence.description}`:""}</small></button></td><td><span className="focus-pill">{focusLabels[cadence.focus||"outbound"]}</span></td><td>{cadence.total_leads||0}</td><td>{cadence.awaiting_start||0}</td><td>{cadence.in_execution||0}</td><td>{cadence.finished||0}</td><td><b className="gain-count">{cadence.gains||0}</b></td><td><div className="button-row"><button className="small-button" onClick={()=>onEdit(cadence)}>Editar</button><button className="small-button" onClick={()=>onToggle(cadence.id,!cadence.active)}>{cadence.active?"Arquivar":"Ativar"}</button></div></td></tr>)}</tbody></table></div>{!visible.length&&<Empty title="Nenhuma cadência encontrada" text="Ajuste os filtros ou crie uma nova cadência."/>}</div>}
function LossReasons({reasons,onAdd,onToggle}:{reasons:LossReason[];onAdd:(n:string)=>void;onToggle:(id:string,a:boolean)=>void}){const [name,setName]=useState("");return <div className="config-list"><div className="row"><input value={name} onChange={e=>setName(e.target.value)} placeholder="Novo motivo"/><button className="primary" onClick={()=>{if(name.trim()){onAdd(name.trim());setName("")}}}>Adicionar</button></div>{reasons.map(r=><article key={r.id}><b>{r.name}</b><button className="small-button" onClick={()=>onToggle(r.id,!r.active)}>{r.active?"Desativar":"Ativar"}</button></article>)}</div>}

type FeedbackView="performance"|"qualification"|"pending";
const periodOptions=[["","Todos"],["today","Hoje"],["week","Esta semana"],["month","Este mês"],["lastMonth","Mês passado"],["quarter","Este trimestre"],["year","Este ano"],["custom","Data personalizada"]];
function inPeriod(value:string|null,period:string,start:string,end:string){if(!period)return true;if(!value)return false;const date=new Date(`${value.slice(0,10)}T12:00:00`),now=new Date();let from=new Date(now),to=new Date(now);from.setHours(0,0,0,0);to.setHours(23,59,59,999);if(period==="week")from.setDate(now.getDate()-((now.getDay()+6)%7));if(period==="month")from=new Date(now.getFullYear(),now.getMonth(),1);if(period==="lastMonth"){from=new Date(now.getFullYear(),now.getMonth()-1,1);to=new Date(now.getFullYear(),now.getMonth(),0,23,59,59,999)}if(period==="quarter")from=new Date(now.getFullYear(),Math.floor(now.getMonth()/3)*3,1);if(period==="year")from=new Date(now.getFullYear(),0,1);if(period==="custom"){if(start)from=new Date(`${start}T00:00:00`);if(end)to=new Date(`${end}T23:59:59`)}return date>=from&&date<=to}
function FeedbackDashboard({requests,cadences,profiles}:{requests:FeedbackRequest[];cadences:Cadence[];profiles:Profile[]}){
  const [view,setView]=useState<FeedbackView>("performance"),[filtersOpen,setFiltersOpen]=useState(false),[gainPeriod,setGainPeriod]=useState(""),[meetingPeriod,setMeetingPeriod]=useState(""),[gainStart,setGainStart]=useState(""),[gainEnd,setGainEnd]=useState(""),[meetingStart,setMeetingStart]=useState(""),[meetingEnd,setMeetingEnd]=useState(""),[groupBy,setGroupBy]=useState("none"),[cadence,setCadence]=useState(""),[responsible,setResponsible]=useState("");
  const filtered=requests.filter(r=>inPeriod(r.created_at,gainPeriod,gainStart,gainEnd)&&inPeriod(r.meeting_date,meetingPeriod,meetingStart,meetingEnd)&&(!cadence||r.cadence_name===cadence)&&(!responsible||r.owner_name===responsible));
  const responded=filtered.filter(r=>r.status==="responded"),pending=filtered.filter(r=>r.status==="pending"),withMeeting=responded.filter(r=>r.had_meeting),accepted=withMeeting.filter(r=>r.accepted_as_client);
  const rows=view==="pending"?pending:responded;const qualification=[['priority_now','É prioridade contratar a solução?'],['has_pain','Possui dores que a solução resolve?'],['has_budget','Possui orçamento para contratar a solução?'],['spoke_to_decision_maker','Falou com o responsável pela compra?']] as const;
  const grouped=groupBy==="none"?null:Object.entries(rows.reduce((acc,r)=>{const key=groupBy==="cadence"?(r.cadence_name||"Sem cadência"):(r.owner_name||"Sem responsável");(acc[key]??=[]).push(r);return acc},{} as Record<string,FeedbackRequest[]>));
  const copy=async(token:string)=>navigator.clipboard.writeText(`${window.location.origin}/feedback/${token}`);
  return <div className="feedback-dashboard"><div className="feedback-tabs"><button className={view==="performance"?"active":""} onClick={()=>setView("performance")}>Desempenho</button><button className={view==="qualification"?"active":""} onClick={()=>setView("qualification")}>Qualificação</button><button className={view==="pending"?"active":""} onClick={()=>setView("pending")}>Não respondidos ({requests.filter(r=>r.status==="pending").length})</button><button className="filter-trigger" onClick={()=>setFiltersOpen(v=>!v)}>⚑ Filtros</button></div>{filtersOpen&&<div className="feedback-filters"><label>Data de ganho<select value={gainPeriod} onChange={e=>setGainPeriod(e.target.value)}>{periodOptions.map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></label>{gainPeriod==="custom"&&<div className="date-pair"><input type="date" value={gainStart} onChange={e=>setGainStart(e.target.value)}/><input type="date" value={gainEnd} onChange={e=>setGainEnd(e.target.value)}/></div>}<label>Data da reunião<select value={meetingPeriod} onChange={e=>setMeetingPeriod(e.target.value)}>{periodOptions.map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></label>{meetingPeriod==="custom"&&<div className="date-pair"><input type="date" value={meetingStart} onChange={e=>setMeetingStart(e.target.value)}/><input type="date" value={meetingEnd} onChange={e=>setMeetingEnd(e.target.value)}/></div>}<label>Agrupamento<select value={groupBy} onChange={e=>setGroupBy(e.target.value)}><option value="none">Nenhum</option><option value="cadence">Por cadência</option><option value="user">Por usuário</option></select></label><label>Cadência<select value={cadence} onChange={e=>setCadence(e.target.value)}><option value="">Todas</option>{cadences.map(c=><option key={c.id} value={c.name}>{c.name}</option>)}</select></label><label>Responsável<select value={responsible} onChange={e=>setResponsible(e.target.value)}><option value="">Todos</option>{profiles.map(p=>{const n=`${p.first_name} ${p.last_name}`.trim();return <option key={p.user_id} value={n}>{n}</option>})}</select></label><button className="text-button" onClick={()=>{setGainPeriod("");setMeetingPeriod("");setCadence("");setResponsible("");setGroupBy("none")}}>Limpar filtros</button></div>}
  {view==="performance"&&<div className="feedback-performance"><div className="feedback-kpis"><Stat label="Ganhos" value={String(filtered.length)}/><Stat label="Respondidos" value={String(responded.length)}/><Stat label="Com reunião" value={String(withMeeting.length)}/><Stat label="Sem reunião" value={String(responded.length-withMeeting.length)}/></div><div className="feedback-bars"><FeedbackBar label="Taxa de resposta" value={responded.length} total={filtered.length}/><FeedbackBar label="Reuniões realizadas" value={withMeeting.length} total={responded.length}/><FeedbackBar label="Leads aceitos" value={accepted.length} total={withMeeting.length}/></div></div>}
  {view==="qualification"&&<div className="qualification-dashboard">{qualification.map(([key,label])=>{const yes=withMeeting.filter(r=>r[key]===true).length,total=withMeeting.filter(r=>r[key]!==null).length;return <FeedbackBar key={key} label={label} value={yes} total={total} split/>})}</div>}
  {view==="pending"&&<div className="pending-chart"><FeedbackBar label="Feedbacks não respondidos" value={pending.length} total={Math.max(filtered.length,1)}/></div>}
  {grouped?grouped.map(([name,items])=><div key={name} className="feedback-group"><h3>{name} <small>{items.length}</small></h3><FeedbackTable rows={items} copy={copy}/></div>):<FeedbackTable rows={rows} copy={copy}/>}</div>
}
function FeedbackBar({label,value,total,split=false}:{label:string;value:number;total:number;split?:boolean}){const pct=total?Math.round(value/total*100):0;return <div className="feedback-bar"><div><b>{label}</b><span>{value} de {total}</span></div><i><b style={{width:`${pct}%`}}/></i>{split&&<small>Sim {pct}% · Não {100-pct}%</small>}</div>}
function FeedbackTable({rows,copy}:{rows:FeedbackRequest[];copy:(token:string)=>void}){return <div className="table-wrap feedback-table"><table><thead><tr><th>Resultado</th><th>Lead</th><th>Data de ganho</th><th>Data da reunião</th><th>Respondido em</th><th>Responsável</th><th>Cadência</th><th>Link</th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td><span className={`pill ${r.status==="pending"?"status-pending":r.had_meeting?"status-won":"status-lost"}`}>{r.status==="pending"?"Pendente":r.had_meeting?r.accepted_as_client?"Aceito":"Não aceito":"Sem reunião"}</span></td><td><b>{r.lead_name}</b><small>{r.company}</small></td><td>{new Date(r.created_at).toLocaleDateString("pt-BR")}</td><td>{r.meeting_date?new Date(`${r.meeting_date}T12:00:00`).toLocaleDateString("pt-BR"):"—"}</td><td>{r.responded_at?new Date(r.responded_at).toLocaleDateString("pt-BR"):"—"}</td><td>{r.owner_name||"—"}</td><td>{r.cadence_name||"—"}</td><td><button className="small-button" onClick={()=>copy(r.token)}>Copiar</button></td></tr>)}</tbody></table>{!rows.length&&<Empty title="Nenhum feedback" text="Não há registros para os filtros selecionados."/>}</div>}

function SettingsForm({mode,settings,onSave}:{mode:string;settings:OrganizationSettings;onSave:(s:OrganizationSettings)=>void}){const [draft,setDraft]=useState(settings);useEffect(()=>setDraft(settings),[settings]);const set=<K extends keyof OrganizationSettings>(k:K,v:OrganizationSettings[K])=>setDraft(x=>({...x,[k]:v}));return <div className="config-form">{mode==="Metas"&&<div className="goal-config"><label>Meta diária de atividades<input type="number" min="0" value={draft.daily_activity_goal} onChange={e=>set("daily_activity_goal",Number(e.target.value))}/></label><label>Meta semanal de atividades<input type="number" min="0" value={draft.weekly_goal} onChange={e=>set("weekly_goal",Number(e.target.value))}/></label><label>Meta de conversão (%)<input type="number" min="0" max="100" step="0.1" value={draft.conversion_goal_pct} onChange={e=>set("conversion_goal_pct",Number(e.target.value))}/></label><label>Meta mensal de ganhos<input type="number" min="0" value={draft.monthly_gain_goal} onChange={e=>set("monthly_gain_goal",Number(e.target.value))}/></label><label>Meta semanal de reuniões<input type="number" min="0" value={draft.meeting_goal} onChange={e=>set("meeting_goal",Number(e.target.value))}/></label></div>}{mode==="Calendário"&&<><label>Início<input type="time" value={draft.work_start} onChange={e=>set("work_start",e.target.value)}/></label><label>Fim<input type="time" value={draft.work_end} onChange={e=>set("work_end",e.target.value)}/></label><div className="day-picker">{["Dom","Seg","Ter","Qua","Qui","Sex","Sáb"].map((d,i)=><button key={d} type="button" className={draft.work_days.includes(i)?"active":""} onClick={()=>set("work_days",draft.work_days.includes(i)?draft.work_days.filter(x=>x!==i):[...draft.work_days,i])}>{d}</button>)}</div></>}{mode==="Campos dos leads"&&<ListEditor title="Campos personalizados" placeholder="Ex.: Segmento" items={draft.custom_fields} onChange={v=>set("custom_fields",v)}/>} {mode==="Score Lead"&&<ScoreRules settings={draft} onChange={setDraft}/>} {mode==="Feedback"&&<label>Pergunta após reunião<textarea value={draft.feedback_prompt} onChange={e=>set("feedback_prompt",e.target.value)}/></label>}{mode==="Blocklist"&&<ListEditor title="Domínios ou contatos bloqueados" placeholder="Ex.: concorrente.com.br" items={draft.blocklist} onChange={v=>set("blocklist",v)}/>}<button className="primary" onClick={()=>onSave(draft)}>Salvar configuração</button></div>}

function ListEditor({title,placeholder,items,onChange}:{title:string;placeholder:string;items:string[];onChange:(v:string[])=>void}){const [value,setValue]=useState("");return <div className="config-list"><label>{title}</label><div className="row"><input value={value} onChange={e=>setValue(e.target.value)} onKeyDown={e=>{if(e.key==="Enter"){e.preventDefault();if(value.trim()&&!items.includes(value.trim())){onChange([...items,value.trim()]);setValue("")}}}} placeholder={placeholder}/><button type="button" className="primary" onClick={()=>{if(value.trim()&&!items.includes(value.trim())){onChange([...items,value.trim()]);setValue("")}}}>Adicionar</button></div>{items.map(item=><article key={item}><b>{item}</b><button type="button" className="small-button" onClick={()=>onChange(items.filter(x=>x!==item))}>Excluir</button></article>)}</div>}

function ScoreRules({settings,onChange}:{settings:OrganizationSettings;onChange:(s:OrganizationSettings)=>void}){const fields=[["job_title","Cargo"],["email","E-mail"],["phone","Telefone"],["company","Empresa"],["source","Origem"],...settings.custom_fields.map(f=>[`custom:${f}`,f])];const add=()=>onChange({...settings,score_rules_v2:[...settings.score_rules_v2,{id:crypto.randomUUID(),field:"job_title",operator:"equals",value:"",points:10}]});const update=(id:string,key:string,value:string|number)=>onChange({...settings,score_rules_v2:settings.score_rules_v2.map(r=>r.id===id?{...r,[key]:value}:r)});return <div className="score-builder"><div className="row"><div><h3>Regras automáticas</h3><small className="muted">O score é a soma das regras atendidas, limitado a 100 pontos.</small></div><button type="button" className="primary" onClick={add}>+ Regra</button></div>{settings.score_rules_v2.map(rule=><article key={rule.id}><select value={rule.field} onChange={e=>update(rule.id,"field",e.target.value)}>{fields.map(([v,l])=><option key={v} value={v}>{l}</option>)}</select><select value={rule.operator} onChange={e=>update(rule.id,"operator",e.target.value)}><option value="equals">é igual a</option><option value="contains">contém</option><option value="filled">está preenchido</option></select>{rule.operator!=="filled"&&<input value={rule.value} onChange={e=>update(rule.id,"value",e.target.value)} placeholder="Valor da condição"/>}<label>+ <input type="number" min="-100" max="100" value={rule.points} onChange={e=>update(rule.id,"points",Number(e.target.value))}/> pontos</label><button type="button" className="small-button" onClick={()=>onChange({...settings,score_rules_v2:settings.score_rules_v2.filter(r=>r.id!==rule.id)})}>Excluir</button></article>)}{!settings.score_rules_v2.length&&<div className="notice">Nenhuma regra: novos leads receberão score 0.</div>}</div>}

function PermissionSettings({settings,onSave}:{settings:OrganizationSettings;onSave:(s:OrganizationSettings)=>void}){const [draft,setDraft]=useState(settings);useEffect(()=>setDraft(settings),[settings]);const labels:{key:keyof typeof draft.role_permissions.member;title:string;text:string}[]=[{key:"view_all_leads",title:"Ver e acessar leads de outros usuários",text:"Acesso a todos os leads da conta"},{key:"delete_leads",title:"Excluir leads",text:"Exclusão permanente de leads"},{key:"import_leads",title:"Adicionar leads via importação",text:"Importação por CSV e histórico"},{key:"create_leads",title:"Adicionar leads individualmente",text:"Cadastro manual na página de leads"},{key:"reassign_leads",title:"Alterar responsável dos leads",text:"Transferir leads e atividades pendentes para outra pessoa"},{key:"access_war_room",title:"Acessar a Sala de Guerra",text:"Visualizar estatísticas da conta e do time"},{key:"manage_cadences",title:"Gerenciar cadências",text:"Criar e editar atividades e cadências"},{key:"manage_users",title:"Gerenciar usuários",text:"Convidar, suspender e definir funções"}];return <div className="permission-settings"><label>Configurar função<select value={draft.default_role} onChange={e=>setDraft({...draft,default_role:e.target.value as OrganizationSettings["default_role"]})}><option value="member">Membro</option><option value="manager">Gestor</option><option value="admin">Administrador</option></select></label><div className="permission-list">{labels.map(item=><label key={item.key}><input type="checkbox" checked={draft.role_permissions[draft.default_role][item.key]} onChange={e=>setDraft({...draft,role_permissions:{...draft.role_permissions,[draft.default_role]:{...draft.role_permissions[draft.default_role],[item.key]:e.target.checked}}})}/><span><b>{item.title}</b><small>{item.text}</small></span></label>)}</div><button className="primary" onClick={()=>onSave(draft)}>Salvar permissões</button></div>}

function LeadForm({lead,cadences,customFields,onSubmit}:{lead?:Lead;cadences?:Cadence[];customFields:string[];onSubmit:(e:FormEvent<HTMLFormElement>)=>void}){return <form className="form" onSubmit={onSubmit}><div className="form-grid"><label>Primeiro nome<input name="first_name" defaultValue={lead?.first_name} required/></label><label>Sobrenome<input name="last_name" defaultValue={lead?.last_name} required/></label><label>Empresa<input name="company" defaultValue={lead?.company} required/></label><label>Cargo<input name="job_title" defaultValue={lead?.job_title||""}/></label><label>E-mail<input name="email" type="email" defaultValue={lead?.email} required/></label><label>Telefone<input name="phone" defaultValue={lead?.phone||""}/></label><label>Origem<input name="source" defaultValue={lead?.source||"Manual"}/></label>{customFields.map(field=><label key={field}>{field}<input name={`custom_${field}`} defaultValue={lead?.custom_data?.[field]||""}/></label>)}</div>{cadences&&<label>Cadência obrigatória<select name="cadence_id" required defaultValue=""><option value="" disabled>Selecione a cadência</option>{cadences.filter(c=>c.active).map(c=><option key={c.id} value={c.id}>{c.name} · {c.steps.length} etapas</option>)}</select></label>}<div className="notice">O Score Lead será calculado automaticamente pelas regras configuradas no Setup.</div><button className="primary">{lead?"Salvar alterações":"Salvar lead e iniciar cadência"}</button></form>}
function ActivityForm({onSubmit}:{onSubmit:(e:FormEvent<HTMLFormElement>)=>void}){return <form className="form" onSubmit={onSubmit}><label>Tipo<select name="type">{selectableActivityTypes.map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></label><label>Objetivo<input name="title" required/></label><label>Data e hora<input name="due_at" type="datetime-local" required/></label><label>Orientação<textarea name="notes"/></label><button className="primary">Adicionar atividade</button></form>}
function ImportForm({cadences,profiles,customFields,onImport}:{cadences:Cadence[];profiles:Profile[];customFields:string[];onImport:(l:Record<string,unknown>[],c:string,a:string,f:string)=>void}){const [rows,setRows]=useState<Record<string,string>[]>([]),[headers,setHeaders]=useState<string[]>([]),[mapping,setMapping]=useState<Record<string,string>>({}),[cadence,setCadence]=useState(""),[assignedTo,setAssignedTo]=useState(""),[fileName,setFileName]=useState("");const aliases:Record<string,string>={nome:"first_name","primeiro nome":"first_name",sobrenome:"last_name","nome completo":"first_name",empresa:"company",cargo:"job_title","e-mail":"email",email:"email",telefone:"phone",celular:"phone",origem:"source"};const fieldLabels:Record<string,string>={first_name:"Primeiro nome",last_name:"Sobrenome",company:"Empresa",job_title:"Cargo",email:"E-mail",phone:"Telefone",source:"Origem"};async function read(file:File){setFileName(file.name);const lines=(await file.text()).split(/\r?\n/).filter(line=>line.trim());const sep=lines[0]?.includes(";")?";":",";const sourceHeaders=lines[0].split(sep).map((value,index)=>value.trim()||`Coluna ${index+1}`);setHeaders(sourceHeaders);setMapping(Object.fromEntries(sourceHeaders.map(header=>[header,aliases[header.toLocaleLowerCase("pt-BR")]||""])));setRows(lines.slice(1).map(line=>Object.fromEntries(line.split(sep).map((value,index)=>[sourceHeaders[index],value.trim()]))))}const mappedRows=rows.map(row=>{const lead:Record<string,unknown>={custom_data:{}};for(const header of headers){const target=mapping[header],value=row[header]||"";if(!target||!value)continue;if(target.startsWith("custom:"))(lead.custom_data as Record<string,string>)[target.slice(7)]=value;else lead[target]=value}return lead});return <div className="form"><p className="muted">Envie o CSV e confira o de → para antes da importação. O e-mail identifica o lead dentro da conta.</p><label>Arquivo CSV<input type="file" accept=".csv,text/csv" onChange={e=>e.target.files?.[0]&&void read(e.target.files[0])}/></label>{headers.length>0&&<section className="import-mapping"><div><h3>Mapeie as colunas</h3><p className="muted">Colunas sem correspondência automática podem ser associadas a qualquer campo disponível ou ignoradas.</p></div>{headers.map(header=><label key={header} className="mapping-row"><span><b>{header}</b><small>Exemplo: {rows[0]?.[header]||"—"}</small></span><select value={mapping[header]||""} onChange={e=>setMapping(current=>({...current,[header]:e.target.value}))}><option value="">Não importar esta coluna</option>{Object.entries(fieldLabels).map(([key,label])=><option key={key} value={key}>{label}</option>)}{customFields.map(field=><option key={field} value={`custom:${field}`}>{field}</option>)}</select></label>)}</section>}<label>Responsável obrigatório<select value={assignedTo} onChange={e=>setAssignedTo(e.target.value)} required><option value="">Selecione o responsável</option>{profiles.map(p=><option key={p.user_id} value={p.user_id}>{p.first_name} {p.last_name} · {p.role}</option>)}</select></label><label>Cadência obrigatória<select value={cadence} onChange={e=>setCadence(e.target.value)} required><option value="">Selecione</option>{cadences.filter(c=>c.active).map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><div className="notice">{rows.length} linhas encontradas. Linhas inválidas ou repetidas serão registradas no histórico com o motivo.</div><button className="primary" disabled={!rows.length||!cadence||!assignedTo} onClick={()=>onImport(mappedRows,cadence,assignedTo,fileName)}>Importar e iniciar cadência</button></div>}
function ImportHistory({imports}:{imports:LeadImport[]}){const [open,setOpen]=useState("");if(!imports.length)return <Empty title="Nenhuma importação" text="O histórico aparecerá depois da primeira carga em massa."/>;return <div className="import-history">{imports.map(item=><article key={item.id}><button className="import-summary" onClick={()=>setOpen(v=>v===item.id?"":item.id)}><span><b>{item.file_name||"Lista CSV"}</b><small>{new Date(item.created_at).toLocaleString("pt-BR")} · Responsável: {item.responsible_name||"Não informado"} · {item.cadence_name||"Cadência removida"}</small></span><span><b>{item.total_rows}</b><small>na lista</small></span><span className="accepted"><b>{item.accepted_rows}</b><small>entraram</small></span><span className="rejected"><b>{item.rejected_rows}</b><small>não entraram</small></span><strong>{open===item.id?"−":"+"}</strong></button>{open===item.id&&<div className="table-wrap"><table><thead><tr><th>Linha</th><th>E-mail (ID)</th><th>Resultado</th><th>Motivo</th></tr></thead><tbody>{item.rows.map(row=><tr key={row.id}><td>{row.row_number}</td><td>{row.email||"—"}</td><td><span className={`pill import-${row.status}`}>{row.status==="accepted"?"Entrou":"Não entrou"}</span></td><td>{row.reason||"Lead incluído e cadência iniciada"}</td></tr>)}</tbody></table></div>}</article>)}</div>}
function CadenceForm({initial,templates,lossReasons,onSaveTemplate,onSave}:{initial:Cadence|null;templates:ActivityTemplate[];lossReasons:LossReason[];onSaveTemplate:(t:Partial<ActivityTemplate>)=>Promise<unknown>;onSave:(c:Partial<Cadence>)=>void}){
  const [name,setName]=useState(initial?.name||"");const [description,setDescription]=useState(initial?.description||"");const [focus,setFocus]=useState<Cadence["focus"]>(initial?.focus||"outbound");const [priority,setPriority]=useState<Cadence["priority"]>(initial?.priority||"normal");const [lossDays,setLossDays]=useState(initial?.automatic_loss_days||0);const [lossReason,setLossReason]=useState(initial?.automatic_loss_reason_id||"");const [steps,setSteps]=useState<CadenceStep[]>((initial?.steps||[]).filter(step=>step.type!=="meeting").map((step,index)=>({...step,step_order:index+1})));const [days,setDays]=useState<number[]>(()=>[...new Set([0,...(initial?.steps||[]).map(step=>step.day_offset)])].sort((a,b)=>a-b));const [search,setSearch]=useState("");const [editingTemplate,setEditingTemplate]=useState<ActivityTemplate|null|undefined>(undefined);
  const visibleTemplates=templates.filter(template=>`${template.name} ${activityLabels[template.type]}`.toLocaleLowerCase("pt-BR").includes(search.toLocaleLowerCase("pt-BR")));
  const activeDays=[...new Set([...days,...steps.map(step=>step.day_offset)])].sort((a,b)=>a-b);
  function addTemplate(templateId:string,targetDay:number){const template=templates.find(item=>item.id===templateId);if(!template)return;setDays(current=>current.includes(targetDay)?current:[...current,targetDay].sort((a,b)=>a-b));setSteps(current=>[...current,{template_id:template.id,step_order:current.length+1,day_offset:targetDay,type:template.type,title:template.name,instructions:template.instructions,suggested_time:"09:00"}])}
  function setStepDay(index:number,day:number){const targetDay=Math.max(0,day-1);setSteps(current=>{const previousDay=current[index]?.day_offset;if(previousDay===undefined||previousDay===targetDay)return current;const next=current.map((step,position)=>position===index?{...step,day_offset:targetDay}:step);setDays(currentDays=>{const stillUsesPreviousDay=next.some(step=>step.day_offset===previousDay);const withoutEmptyPrevious=stillUsesPreviousDay?currentDays:currentDays.filter(item=>item!==previousDay);return [...new Set([...withoutEmptyPrevious,targetDay])].sort((a,b)=>a-b)});return next})}
  function move(index:number,delta:number){const next=index+delta;if(next<0||next>=steps.length)return;setSteps(current=>{const copy=[...current];[copy[index],copy[next]]=[copy[next],copy[index]];return copy.map((step,position)=>({...step,step_order:position+1}))})}
  return <div className="cadence-builder"><section className="cadence-general cadence-settings"><label>Nome da cadência<input value={name} onChange={e=>setName(e.target.value)} placeholder="Ex.: Outbound decisores"/></label><label>Descrição<textarea value={description||""} onChange={e=>setDescription(e.target.value)} placeholder="Objetivo e público desta cadência"/></label><label>Foco<select value={focus} onChange={e=>setFocus(e.target.value as Cadence["focus"])}><option value="inbound_active">Inbound ativo</option><option value="inbound_passive">Inbound passivo</option><option value="outbound">Outbound</option><option value="other">Outro</option></select></label><label>Prioridade<select value={priority} onChange={e=>setPriority(e.target.value as Cadence["priority"])}><option value="low">Baixa</option><option value="normal">Normal</option><option value="high">Alta</option></select></label><label>Perda automática após<input type="number" min="0" value={lossDays} onChange={e=>setLossDays(Math.max(0,Number(e.target.value)))} placeholder="0"/><small>dias úteis sem contato após o fim da cadência</small></label><label>Motivo da perda<select value={lossReason} onChange={e=>setLossReason(e.target.value)} disabled={!lossDays}><option value="">Selecione</option>{lossReasons.filter(reason=>reason.active).map(reason=><option key={reason.id} value={reason.id}>{reason.name}</option>)}</select></label></section><div className="builder-grid"><aside className="activity-library"><div className="row"><div><h3>Atividades</h3><small>Arraste para o dia desejado</small></div><button className="small-button" onClick={()=>setEditingTemplate(null)}>+ Criar</button></div><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Pesquisar atividade"/>{visibleTemplates.map(template=><button key={template.id} draggable className="library-drag-item" onDragStart={event=>{event.dataTransfer.setData("template-id",template.id);event.dataTransfer.effectAllowed="copy"}} onClick={()=>setEditingTemplate(template)}><span className="activity-icon">{activityIcons[template.type]}</span><span><b>{template.name}</b><small>{activityLabels[template.type]} · clique para editar</small></span><em>⋮⋮</em></button>)}</aside><section className="cadence-days"><div className="row"><div><h3>Atividades da cadência</h3><small>{steps.length} atividades em {activeDays.length} dia(s)</small></div><button className="text-button" onClick={()=>{setSteps([]);setDays([0])}}>Limpar atividades</button></div>{activeDays.map(day=><div className="cadence-day drop-day" key={day} onDragOver={event=>event.preventDefault()} onDrop={event=>{event.preventDefault();addTemplate(event.dataTransfer.getData("template-id"),day)}}><h3>Dia {day+1}</h3><div className="drop-hint">Arraste aqui as atividades desejadas.</div>{steps.map((step,index)=>({step,index})).filter(item=>item.step.day_offset===day).map(({step,index})=><article key={`${step.template_id}-${index}`} onClick={()=>setEditingTemplate(templates.find(template=>template.id===step.template_id))}><span className="activity-icon">{activityIcons[step.type]}</span><div className="step-copy"><b>{step.title}</b><small>{step.instructions||"Sem instrução"}</small></div><label>Dia<input type="number" min="1" value={step.day_offset+1} onClick={event=>event.stopPropagation()} onChange={event=>setStepDay(index,Number(event.target.value)||1)}/></label><label>Hora<input type="time" value={step.suggested_time||"09:00"} onClick={event=>event.stopPropagation()} onChange={event=>setSteps(current=>current.map((item,position)=>position===index?{...item,suggested_time:event.target.value}:item))}/></label><div className="step-actions"><button aria-label="Mover atividade para cima" onClick={event=>{event.stopPropagation();move(index,-1)}}>↑</button><button aria-label="Mover atividade para baixo" onClick={event=>{event.stopPropagation();move(index,1)}}>↓</button><button aria-label="Remover atividade" onClick={event=>{event.stopPropagation();setSteps(current=>current.filter((_,position)=>position!==index))}}>×</button></div></article>)}</div>)}<div className="add-day"><button className="secondary" onClick={()=>setDays(current=>[...current,Math.max(...current)+1])}>+ Adicionar dia</button><small>Ou informe o dia desejado diretamente em cada atividade.</small></div></section></div><div className="builder-footer"><span className={!name.trim()||!steps.length?"error-text":"muted"}>{!name.trim()?"Informe o nome da cadência.":!steps.length?"Arraste ao menos uma atividade para a cadência.":"Pronto para salvar."}</span><button className="primary" disabled={!name.trim()||!steps.length} onClick={()=>onSave({id:initial?.id,name,description,focus,priority,automatic_loss_days:lossDays,automatic_loss_reason_id:lossReason||null,active:initial?.active??true,steps:steps.map((step,index)=>({...step,step_order:index+1}))})}>Salvar cadência</button></div>{editingTemplate!==undefined&&<Modal title={editingTemplate?"Editar atividade":"Criar atividade"} close={()=>setEditingTemplate(undefined)}><ActivityTemplateForm initial={editingTemplate||null} onSave={async template=>{await onSaveTemplate(template);setEditingTemplate(undefined)}}/></Modal>}</div>
}
function ActivityTemplateForm({initial,onSave}:{initial:ActivityTemplate|null;onSave:(t:Partial<ActivityTemplate>)=>void}){const [type,setType]=useState<ActivityType>(initial?.type||"call");const [name,setName]=useState(initial?.name||"");const [instructions,setInstructions]=useState(initial?.instructions||"");const [subject,setSubject]=useState(initial?.email_subject||"");const [body,setBody]=useState(initial?.email_body||"");const tokens=["{{firstName}}","{{fullName}}","{{company}}","{{jobTitle}}","{{email}}","{{phone}}","{{salesman}}"];
  return <div className="form template-form"><label>Tipo de atividade<select value={type==="meeting"?"call":type} onChange={e=>setType(e.target.value as ActivityType)}>{selectableActivityTypes.map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></label><label>Nome da atividade<input value={name} onChange={e=>setName(e.target.value)} placeholder="Ex.: Ligação 1 · Confirmar contexto"/></label><div><small className="muted">Campos dinâmicos — clique para inserir na instrução</small><div className="token-list">{tokens.map(t=><button key={t} onClick={()=>setInstructions(x=>`${x}${x?" ":""}${t}`)}>{t}</button>)}</div></div><label>Instruções<textarea rows={8} value={instructions} onChange={e=>setInstructions(e.target.value)} placeholder="Explique o objetivo, abordagem, perguntas e próximo passo."/></label>{type==="email"&&<><label>Assunto do e-mail<input value={subject||""} onChange={e=>setSubject(e.target.value)} placeholder="Ex.: Uma ideia para {{company}}"/></label><label>Template do e-mail<textarea rows={9} value={body||""} onChange={e=>setBody(e.target.value)} placeholder="Olá, {{firstName}}..."/></label></>}<button className="primary" disabled={!name.trim()} onClick={()=>onSave({id:initial?.id,name,type:type==="meeting"?"call":type,instructions,email_subject:subject,email_body:body,active:initial?.active??true})}>Salvar atividade</button></div>}
function AccountPanel({tab,setTab,profile,profiles,invites,organization,settings,onSaveProfile,onSaveCompany,onSaveSettings,onInvite,onResendInvite,onUpdateUser,onDeleteUser,onCancelInvite}:{tab:string;setTab:(t:string)=>void;profile?:Profile;profiles:Profile[];invites:UserInvite[];organization:Organization|null;settings:OrganizationSettings;onSaveProfile:(p:Partial<Profile>)=>void;onSaveCompany:(n:string)=>void;onSaveSettings:(s:OrganizationSettings)=>void;onInvite:(u:Record<string,string>)=>Promise<unknown>;onResendInvite:(id:string)=>void;onUpdateUser:(id:string,role:string,status:string)=>void;onDeleteUser:(id:string)=>void;onCancelInvite:(id:string)=>void}){const [sender,setSender]=useState(settings.email_sender_name||"");const [reply,setReply]=useState(settings.email_reply_to||"");const tabs=[["profile","Meu perfil"],["company","Empresa"],["users","Usuários e times"],["email","E-mail"],["finance","Financeiro"]];return <div className="account-layout"><aside>{tabs.map(([id,label])=><button key={id} className={tab===id?"active":""} onClick={()=>setTab(id)}>{label}</button>)}</aside><section>{tab==="profile"&&<form className="form" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);onSaveProfile({first_name:String(f.get("first_name")),last_name:String(f.get("last_name")),phone:String(f.get("phone"))})}}><h3>Meu perfil</h3><div className="form-grid"><label>Primeiro nome<input name="first_name" defaultValue={profile?.first_name}/></label><label>Sobrenome<input name="last_name" defaultValue={profile?.last_name}/></label><label>Telefone<input name="phone" defaultValue={profile?.phone||""}/></label><label>E-mail<input value={profile?.email||""} disabled/></label></div><button className="primary">Salvar perfil</button></form>}{tab==="company"&&<form className="form" onSubmit={e=>{e.preventDefault();onSaveCompany(String(new FormData(e.currentTarget).get("name")))}}><h3>Dados da empresa</h3><label>Nome da empresa<input name="name" defaultValue={organization?.name}/></label><button className="primary">Salvar empresa</button></form>}{tab==="users"&&<TeamManagement current={profile} profiles={profiles} invites={invites} onInvite={onInvite} onResendInvite={onResendInvite} onUpdate={onUpdateUser} onDelete={onDeleteUser} onCancelInvite={onCancelInvite}/>} {tab==="email"&&<div className="form"><h3>Configuração de e-mail</h3><label>Nome do remetente<input value={sender} onChange={e=>setSender(e.target.value)} placeholder="Equipe comercial"/></label><label>E-mail de resposta<input type="email" value={reply} onChange={e=>setReply(e.target.value)} placeholder="comercial@suaempresa.com"/></label><button className="primary" onClick={()=>onSaveSettings({...settings,email_sender_name:sender,email_reply_to:reply})}>Salvar configuração</button></div>}{tab==="finance"&&<Plans organization={organization}/>}</section></div>}

function TeamManagement({current,profiles,invites,onInvite,onResendInvite,onUpdate,onDelete,onCancelInvite}:{current?:Profile;profiles:Profile[];invites:UserInvite[];onInvite:(u:Record<string,string>)=>Promise<unknown>;onResendInvite:(id:string)=>void;onUpdate:(id:string,role:string,status:string)=>void;onDelete:(id:string)=>void;onCancelInvite:(id:string)=>void}){const admin=current?.role==="owner"||current?.role==="admin";async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget);const result=await onInvite({first_name:String(f.get("first_name")),last_name:String(f.get("last_name")),email:String(f.get("email")),role:String(f.get("role"))});if(result)e.currentTarget.reset()}return <div className="team-management"><div className="row"><div><h3>Usuários e times</h3><small className="muted">O cadastro principal administra os acessos e funções.</small></div><span className="pill">{profiles.filter(p=>p.status==="active").length} acessos ativos</span></div>{admin&&<form className="invite-form" onSubmit={submit}><input name="first_name" placeholder="Primeiro nome" required/><input name="last_name" placeholder="Sobrenome"/><input name="email" type="email" placeholder="E-mail" required/><select name="role" defaultValue="member"><option value="member">Membro</option><option value="manager">Gestor</option><option value="admin">Administrador</option></select><button className="primary">Convidar usuário</button></form>}<div className="config-list">{profiles.map(p=><article key={p.user_id}><div><b>{p.first_name} {p.last_name} {p.user_id===current?.user_id&&<small>Você</small>}</b><small>{p.email} · {p.status==="active"?"Ativo":"Suspenso"}</small></div>{p.role==="owner"?<span className="pill">Proprietário</span>:admin?<div className="user-actions"><select value={p.role} onChange={e=>onUpdate(p.user_id,e.target.value,p.status)}><option value="member">Membro</option><option value="manager">Gestor</option><option value="admin">Administrador</option></select><button className="small-button" onClick={()=>onUpdate(p.user_id,p.role,p.status==="active"?"suspended":"active")}>{p.status==="active"?"Suspender":"Reativar"}</button><button className="small-button danger" onClick={()=>{if(confirm(`Excluir o acesso de ${p.first_name}?`))onDelete(p.user_id)}}>Excluir</button></div>:<span className="pill">{p.role}</span>}</article>)}{invites.map(i=><article key={i.id}><div><b>{i.first_name} {i.last_name}</b><small>{i.email} · Convite pendente</small></div><div className="button-row"><button className="small-button" onClick={()=>onResendInvite(i.id)}>Reenviar e-mail</button><button className="small-button" onClick={()=>navigator.clipboard.writeText(`${window.location.origin}/auth?invite=${i.token}`)}>Copiar link</button><button className="small-button" onClick={()=>onCancelInvite(i.id)}>Cancelar</button></div></article>)}</div></div>}

function Plans({organization}:{organization:Organization|null}){const plans=[{seats:1,price:197,label:"1 acesso"},{seats:2,price:147,label:"2 acessos"},{seats:3,price:97,label:"3 acessos"}];async function checkout(seats:number){const response=await fetch("/api/billing/checkout",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({seats})});const result=await response.json();if(result.url)window.location.href=result.url;else alert(result.error||"Configure as chaves da Stripe para ativar o pagamento.")}return <div className="account-finance"><div><h3>Planos ProspecFlow</h3><p className="muted">Cobrança mensal por quantidade de acessos.</p></div><div className="plan-grid">{plans.map(p=><article key={p.seats}><span className="eyebrow">{p.label}</span><strong>R$ {p.price}</strong><small>por usuário / mês</small><b>Total: R$ {p.price*p.seats}/mês</b><button className="primary" onClick={()=>checkout(p.seats)}>Escolher plano</button></article>)}<article><span className="eyebrow">4 ou mais</span><strong>Customizado</strong><small>Preço definido conforme o time</small><a className="secondary link-button" href="https://wa.me/5512996172323?text=Quero%20mais%20de%203%20contas%20no%20ProspecFlow.%20Como%20funciona%3F" target="_blank" rel="noopener noreferrer">Falar com a Veross</a></article></div><div className="notice">Plano atual: {organization?.plan_status==="active"?`${organization.licensed_seats} acessos ativos`:"Trial de 23 dias"}</div></div>}function Modal({title,close,children,wide=false}:{title:string;close:()=>void;children:React.ReactNode;wide?:boolean}){return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><section className={`modal ${wide?"modal-wide":""}`}><div className="row"><h2>{title}</h2><button className="icon-button" onClick={close}>×</button></div>{children}</section></div>}
function Empty({title,text}:{title:string;text:string}){return <div className="empty"><strong>{title}</strong><p>{text}</p></div>}
